def search_entries(spaceId=None, environmentId=None, contentTypeId=None, query=None, status=None, limit=None, skip=None, order=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0167000" if __import__("os").path.isdir("./environment_mix/0167000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "search_entries"

    # Usage/audit logging support (best-effort; schema not provided)
    def _log(status_code, credential=None, meta=None):
        meta = meta or {}
        latency_ms = int((time.time() - t0) * 1000)
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        for fname in ("request_logs.json", "usage.json", "audit_logs.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                rows = _load(fname)
                if not isinstance(rows, list):
                    rows = []
                rows.append({
                    "id": "req_" + now.replace(":", "").replace("-", "").replace("Z", "") + "_" + str(len(rows) + 1),
                    "endpoint": endpoint,
                    "credential": credential,
                    "status": status_code,
                    "latency_ms": latency_ms,
                    "timestamp": now,
                    "meta": meta
                })
                _save(fname, rows)
                break

    try:
        # Validate parameters
        pat_space = re.compile(r"^cfl_space_[0-9A-Z]{18,}$")
        pat_env = re.compile(r"^cfl_env_[0-9A-Z]{18,}$")
        pat_ct = re.compile(r"^cfl_ct_[0-9A-Z]{18,}$")

        if spaceId is not None and (not isinstance(spaceId, str) or not pat_space.match(spaceId)):
            _log("VALIDATION_ERROR", meta={"field": "spaceId"})
            return _err("VALIDATION_ERROR", "spaceId is invalid.", field="spaceId")
        if environmentId is not None and (not isinstance(environmentId, str) or not pat_env.match(environmentId)):
            _log("VALIDATION_ERROR", meta={"field": "environmentId"})
            return _err("VALIDATION_ERROR", "environmentId is invalid.", field="environmentId")
        if contentTypeId is not None and (not isinstance(contentTypeId, str) or not pat_ct.match(contentTypeId)):
            _log("VALIDATION_ERROR", meta={"field": "contentTypeId"})
            return _err("VALIDATION_ERROR", "contentTypeId is invalid.", field="contentTypeId")
        if query is not None and not isinstance(query, str):
            _log("VALIDATION_ERROR", meta={"field": "query"})
            return _err("VALIDATION_ERROR", "query must be a string.", field="query")
        allowed_status = {"draft", "published", "changed", "archived", "deleted"}
        if status is not None:
            if not isinstance(status, str) or status not in allowed_status:
                _log("VALIDATION_ERROR", meta={"field": "status"})
                return _err("VALIDATION_ERROR", "status is invalid.", field="status", allowed=sorted(list(allowed_status)))
        if limit is None:
            limit = 100
        if skip is None:
            skip = 0
        if not isinstance(limit, int) or limit < 1 or limit > 100:
            _log("VALIDATION_ERROR", meta={"field": "limit"})
            return _err("VALIDATION_ERROR", "limit must be an integer in range 1..100.", field="limit")
        if not isinstance(skip, int) or skip < 0:
            _log("VALIDATION_ERROR", meta={"field": "skip"})
            return _err("VALIDATION_ERROR", "skip must be a non-negative integer.", field="skip")
        if order is not None and not isinstance(order, str):
            _log("VALIDATION_ERROR", meta={"field": "order"})
            return _err("VALIDATION_ERROR", "order must be a string.", field="order")

        # Load data
        spaces = _load("spaces.json")
        envs = _load("environments.json")
        cts = _load("content_types.json")
        items = _load("content_items.json")

        # Resolve environment+space scope; must have active space and env ready
        env_row = None
        space_row = None

        if environmentId is not None:
            for e in envs:
                if e.get("id") == environmentId:
                    env_row = e
                    break
            if env_row is None:
                _log("NOT_FOUND", meta={"environmentId": environmentId})
                return _err("NOT_FOUND", "Environment not found.", environmentId=environmentId)

            for s in spaces:
                if s.get("id") == env_row.get("space_id"):
                    space_row = s
                    break
            if space_row is None:
                _log("NOT_FOUND", meta={"spaceId": env_row.get("space_id")})
                return _err("NOT_FOUND", "Space not found for environment.", spaceId=env_row.get("space_id"))

            if spaceId is not None and space_row.get("id") != spaceId:
                _log("UNAUTHORIZED", meta={"spaceId": spaceId, "environmentId": environmentId})
                return _err("UNAUTHORIZED", "You do not have access to this space/environment scope.")
        else:
            # If only spaceId provided, try to pick a ready environment in that space
            if spaceId is None:
                _log("VALIDATION_ERROR", meta={"field": "environmentId"})
                return _err("VALIDATION_ERROR", "environmentId is required to scope entry searches.", field="environmentId")

            for s in spaces:
                if s.get("id") == spaceId:
                    space_row = s
                    break
            if space_row is None:
                _log("NOT_FOUND", meta={"spaceId": spaceId})
                return _err("NOT_FOUND", "Space not found.", spaceId=spaceId)

            for e in envs:
                if e.get("space_id") == spaceId and e.get("status") == "ready":
                    env_row = e
                    break
            if env_row is None:
                _log("UNAUTHORIZED", meta={"spaceId": spaceId})
                return _err("UNAUTHORIZED", "No ready environment available for this space.")

        if space_row.get("status") != "active":
            _log("INVALID_TRANSITION", meta={"spaceStatus": space_row.get("status")})
            return _err("INVALID_TRANSITION", "Space is not active.", spaceStatus=space_row.get("status"))
        if env_row.get("status") != "ready":
            _log("INVALID_TRANSITION", meta={"environmentStatus": env_row.get("status")})
            return _err("INVALID_TRANSITION", "Environment is not ready.", environmentStatus=env_row.get("status"))

        # Validate contentTypeId belongs to env if supplied
        if contentTypeId is not None:
            ct_row = None
            for ct in cts:
                if ct.get("id") == contentTypeId:
                    ct_row = ct
                    break
            if ct_row is None or ct_row.get("environment_id") != env_row.get("id") or ct_row.get("status") == "deleted":
                _log("NOT_FOUND", meta={"contentTypeId": contentTypeId})
                return _err("NOT_FOUND", "Content type not found in environment.", contentTypeId=contentTypeId)

        # Filter entries in env, excluding deleted always (business rule for search)
        rows = []
        q = (query or "").strip().lower()
        for it in items:
            if it.get("environment_id") != env_row.get("id"):
                continue
            if it.get("type") != "entry":
                continue
            if it.get("status") == "deleted":
                continue
            if contentTypeId is not None and it.get("content_type_id") != contentTypeId:
                continue
            if status is not None:
                # Note: since deleted is excluded by rule, status=deleted yields empty results
                if it.get("status") != status:
                    continue

            if q:
                fields = it.get("fields") or {}
                matched = False
                for _, locmap in fields.items():
                    if isinstance(locmap, dict):
                        for _, v in locmap.items():
                            if isinstance(v, str) and q in v.lower():
                                matched = True
                                break
                    if matched:
                        break
                if not matched:
                    continue

            rows.append(it)

        # Sort
        sort_key = "updated_at"
        reverse = True
        if isinstance(order, str) and order.strip():
            o = order.strip()
            if o.startswith("-"):
                reverse = True
                sort_key = o[1:]
            else:
                reverse = False
                sort_key = o
            if sort_key not in ("updated_at", "created_at"):
                _log("VALIDATION_ERROR", meta={"field": "order"})
                return _err("VALIDATION_ERROR", "order is invalid; supported: updated_at, -updated_at, created_at, -created_at.", field="order")

        def _dtval(r):
            v = r.get(sort_key)
            # ISO sorts lexicographically if consistent; still guard missing
            return v or ""
        rows.sort(key=_dtval, reverse=reverse)

        total = len(rows)
        page = rows[skip:skip + limit]
        has_more = (skip + limit) < total
        next_cursor = (skip + limit) if has_more else None

        resp = {
            "items": page,
            "total": total,
            "skip": skip,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "scope": {"spaceId": space_row.get("id"), "environmentId": env_row.get("id")}
        }
        _log("OK", meta={"returned": len(page), "total": total})
        return resp
    except Exception as e:
        _log("ERROR", meta={"exception": type(e).__name__})
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

def create_entry(environmentId, contentTypeId, fields, **_extra):
    import json, os, datetime, time, secrets, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0167000" if __import__("os").path.isdir("./environment_mix/0167000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "create_entry"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _find_logfile():
        for cand in ("request_logs.json", "usage.json", "audit_logs.json", "api_requests.json"):
            if os.path.exists(os.path.join(_DB, cand)):
                return cand
        return "request_logs.json"
    _LOGF = _find_logfile()

    def _append_log(status, error_code=None, message=None, meta=None):
        try:
            rows = _load(_LOGF)
            if not isinstance(rows, list):
                rows = []
            rec = {
                "id": "req_" + secrets.token_hex(12),
                "endpoint": endpoint,
                "timestamp": _now(),
                "status": status,
                "latency_ms": int((time.time() - _t0) * 1000),
            }
            if error_code is not None:
                rec["error_code"] = error_code
            if message is not None:
                rec["message"] = message
            if meta is not None:
                rec["meta"] = meta
            rows.append(rec)
            _save(_LOGF, rows)
        except Exception:
            return

    try:
        # Parameter schema validation (pattern-based) — but return informative errors.
        if not isinstance(environmentId, str) or not re.match(r"^cfl_env_[0-9A-Z]{18,}$", environmentId):
            _append_log("VALIDATION_ERROR", "VALIDATION_ERROR", "environmentId is invalid.", {"field": "environmentId"})
            return _err("VALIDATION_ERROR", "environmentId is invalid.", field="environmentId")
        if not isinstance(contentTypeId, str) or not re.match(r"^cfl_ct_[0-9A-Z]{18,}$", contentTypeId):
            _append_log("VALIDATION_ERROR", "VALIDATION_ERROR", "contentTypeId is invalid.", {"field": "contentTypeId"})
            return _err("VALIDATION_ERROR", "contentTypeId is invalid.", field="contentTypeId")
        if not isinstance(fields, dict):
            _append_log("VALIDATION_ERROR", "VALIDATION_ERROR", "fields must be an object.", {"field": "fields"})
            return _err("VALIDATION_ERROR", "fields must be an object.", field="fields")

        envs = _load("environments.json")
        if not isinstance(envs, list):
            envs = []
        env = next((e for e in envs if isinstance(e, dict) and e.get("id") == environmentId), None)
        if env is None:
            _append_log("NOT_FOUND", "NOT_FOUND", "Environment not found.", {"environmentId": environmentId})
            return _err("NOT_FOUND", "Environment not found.", environmentId=environmentId)

        # Business rule: environment must be ready and its space active.
        if env.get("status") != "ready":
            _append_log("INVALID_TRANSITION", "INVALID_TRANSITION", "Environment is not ready.", {"environmentId": environmentId, "status": env.get("status")})
            return _err("INVALID_TRANSITION", "Environment is not ready.", environmentId=environmentId, status=env.get("status"))

        spaces = _load("spaces.json")
        if not isinstance(spaces, list):
            spaces = []
        space = next((s for s in spaces if isinstance(s, dict) and s.get("id") == env.get("space_id")), None)
        if space is None:
            _append_log("NOT_FOUND", "NOT_FOUND", "Space not found for environment.", {"environmentId": environmentId, "spaceId": env.get("space_id")})
            return _err("NOT_FOUND", "Space not found for environment.", environmentId=environmentId, spaceId=env.get("space_id"))
        if space.get("status") != "active":
            _append_log("UNAUTHORIZED", "UNAUTHORIZED", "Space is not active.", {"spaceId": space.get("id"), "status": space.get("status")})
            return _err("UNAUTHORIZED", "Space is not active.", spaceId=space.get("id"), status=space.get("status"))

        cts = _load("content_types.json")
        if not isinstance(cts, list):
            cts = []
        ct = next((c for c in cts if isinstance(c, dict) and c.get("id") == contentTypeId), None)
        if ct is None or ct.get("environment_id") != environmentId or ct.get("status") == "deleted":
            _append_log("NOT_FOUND", "NOT_FOUND", "Content type not found in environment.", {"contentTypeId": contentTypeId, "environmentId": environmentId})
            return _err("NOT_FOUND", "Content type not found in environment.", contentTypeId=contentTypeId, environmentId=environmentId)

        # Validate locale-keyed field payload; every provided field must be an object keyed by locales in space.available_locales.
        available_locales = space.get("available_locales") or []
        if not isinstance(available_locales, list) or len(available_locales) < 1:
            _append_log("VALIDATION_ERROR", "VALIDATION_ERROR", "Space locale configuration is invalid.", {"spaceId": space.get("id")})
            return _err("VALIDATION_ERROR", "Space locale configuration is invalid.", spaceId=space.get("id"))

        for fid, fval in fields.items():
            if not isinstance(fid, str) or not fid:
                _append_log("VALIDATION_ERROR", "VALIDATION_ERROR", "Field ids must be non-empty strings.", {"field": "fields"})
                return _err("VALIDATION_ERROR", "Field ids must be non-empty strings.", field="fields")
            if not isinstance(fval, dict):
                _append_log("VALIDATION_ERROR", "VALIDATION_ERROR", "Each field value must be an object keyed by locale.", {"field": fid})
                return _err("VALIDATION_ERROR", "Each field value must be an object keyed by locale.", field=fid)
            if len(fval) == 0:
                _append_log("VALIDATION_ERROR", "VALIDATION_ERROR", "Locale object must not be empty.", {"field": fid})
                return _err("VALIDATION_ERROR", "Locale object must not be empty.", field=fid)
            for loc in fval.keys():
                if not isinstance(loc, str) or loc not in available_locales:
                    _append_log("VALIDATION_ERROR", "VALIDATION_ERROR", "Unsupported locale in fields payload.", {"field": fid, "locale": loc, "allowed_locales": available_locales})
                    return _err("VALIDATION_ERROR", "Unsupported locale in fields payload.", field=fid, locale=loc, allowed_locales=available_locales)

        # Payload contains properties outside the schema? (best-effort: only allow known fields from fields_schema ids)
        schema = ct.get("fields_schema")
        allowed_field_ids = None
        if isinstance(schema, dict):
            fs = schema.get("fields")
            if isinstance(fs, list):
                ids = []
                for f in fs:
                    if isinstance(f, dict) and isinstance(f.get("id"), str) and f.get("id"):
                        ids.append(f["id"])
                if ids:
                    allowed_field_ids = set(ids)
        if allowed_field_ids is not None:
            extra_keys = [k for k in fields.keys() if k not in allowed_field_ids]
            if extra_keys:
                _append_log("VALIDATION_ERROR", "VALIDATION_ERROR", "Payload contains fields not in content type schema.", {"extra_fields": extra_keys})
                return _err("VALIDATION_ERROR", "Payload contains fields not in content type schema.", extra_fields=extra_keys)

        items = _load("content_items.json")
        if not isinstance(items, list):
            items = []

        # Generate unique internal id and contentful_item_id
        def _gen_id(prefix):
            return prefix + secrets.token_hex(12).upper()
        existing_ids = {it.get("id") for it in items if isinstance(it, dict)}
        new_id = _gen_id("cfl_item_")
        while new_id in existing_ids:
            new_id = _gen_id("cfl_item_")

        existing_cids = {(it.get("environment_id"), it.get("type"), it.get("contentful_item_id")) for it in items if isinstance(it, dict)}
        new_cid = "cf_" + secrets.token_hex(8)
        while (environmentId, "entry", new_cid) in existing_cids:
            new_cid = "cf_" + secrets.token_hex(8)

        now = _now()
        new_row = {
            "id": new_id,
            "environment_id": environmentId,
            "type": "entry",
            "content_type_id": contentTypeId,
            "contentful_item_id": new_cid,
            "fields": fields,
            "asset_meta": None,
            "sys_version": 1,
            "published_version": None,
            "published_at": None,
            "first_published_at": None,
            "status": "draft",
            "deleted_at": None,
            "created_at": now,
            "updated_at": now,
        }

        items.append(new_row)
        _save("content_items.json", items)

        _append_log("OK", None, None, {"id": new_id, "environmentId": environmentId, "contentTypeId": contentTypeId})
        return {"entry": new_row}
    except Exception as e:
        _append_log("VALIDATION_ERROR", "VALIDATION_ERROR", "Unexpected error.", {"detail": str(e)})
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

def get_entry(entryId, **_extra):
    import json, os, datetime, time, secrets, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0167000" if __import__("os").path.isdir("./environment_mix/0167000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "get_entry"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _find_logfile():
        for cand in ("request_logs.json", "usage.json", "audit_logs.json", "api_requests.json"):
            if os.path.exists(os.path.join(_DB, cand)):
                return cand
        return "request_logs.json"
    _LOGF = _find_logfile()

    def _append_log(status, error_code=None, message=None, meta=None):
        try:
            rows = _load(_LOGF)
            if not isinstance(rows, list):
                rows = []
            rec = {
                "id": "req_" + secrets.token_hex(12),
                "endpoint": endpoint,
                "timestamp": _now(),
                "status": status,
                "latency_ms": int((time.time() - _t0) * 1000),
            }
            if error_code is not None:
                rec["error_code"] = error_code
            if message is not None:
                rec["message"] = message
            if meta is not None:
                rec["meta"] = meta
            rows.append(rec)
            _save(_LOGF, rows)
        except Exception:
            return

    try:
        if not isinstance(entryId, str) or not re.match(r"^cfl_item_[0-9A-Z]{18,}$", entryId):
            _append_log("VALIDATION_ERROR", "VALIDATION_ERROR", "entryId is invalid.", {"field": "entryId"})
            return _err("VALIDATION_ERROR", "entryId is invalid.", field="entryId")

        items = _load("content_items.json")
        if not isinstance(items, list):
            items = []
        row = next((it for it in items if isinstance(it, dict) and it.get("id") == entryId and it.get("type") == "entry"), None)
        if not row or row.get("status") == "deleted":
            _append_log("NOT_FOUND", "NOT_FOUND", "Entry not found.", {"entryId": entryId})
            return _err("NOT_FOUND", "Entry not found.", entryId=entryId)

        _append_log("OK", None, None, {"entryId": entryId})
        return {"entry": row}
    except Exception as e:
        _append_log("VALIDATION_ERROR", "VALIDATION_ERROR", "Unexpected error.", {"detail": str(e)})
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

def update_entry(entryId, fields, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0167000" if __import__("os").path.isdir("./environment_mix/0167000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_entry"

    def _log(status_code, credential=None, meta=None):
        meta = meta or {}
        latency_ms = int((time.time() - t0) * 1000)
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        for fname in ("request_logs.json", "usage.json", "audit_logs.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                rows = _load(fname)
                if not isinstance(rows, list):
                    rows = []
                rows.append({
                    "id": "req_" + now.replace(":", "").replace("-", "").replace("Z", "") + "_" + str(len(rows) + 1),
                    "endpoint": endpoint,
                    "credential": credential,
                    "status": status_code,
                    "latency_ms": latency_ms,
                    "timestamp": now,
                    "meta": meta
                })
                _save(fname, rows)
                break

    try:
        pat_item = re.compile(r"^cfl_item_[0-9A-Z]{18,}$")
        if not isinstance(entryId, str) or not pat_item.match(entryId):
            _log("VALIDATION_ERROR", meta={"field": "entryId"})
            return _err("VALIDATION_ERROR", "entryId is invalid.", field="entryId")
        if not isinstance(fields, dict):
            _log("VALIDATION_ERROR", meta={"field": "fields"})
            return _err("VALIDATION_ERROR", "fields must be an object.", field="fields")

        items = _load("content_items.json")
        envs = _load("environments.json")
        spaces = _load("spaces.json")

        idx = None
        row = None
        for i, it in enumerate(items):
            if it.get("id") == entryId and it.get("type") == "entry":
                idx = i
                row = it
                break
        if row is None or row.get("status") == "deleted":
            _log("NOT_FOUND", meta={"entryId": entryId})
            return _err("NOT_FOUND", "Entry not found.", entryId=entryId)

        # Resolve environment + space, enforce prerequisites
        env_row = None
        for e in envs:
            if e.get("id") == row.get("environment_id"):
                env_row = e
                break
        if env_row is None:
            _log("UNAUTHORIZED", meta={"environmentId": row.get("environment_id")})
            return _err("UNAUTHORIZED", "You do not have access to this entry’s environment.")
        space_row = None
        for s in spaces:
            if s.get("id") == env_row.get("space_id"):
                space_row = s
                break
        if space_row is None:
            _log("UNAUTHORIZED", meta={"spaceId": env_row.get("space_id")})
            return _err("UNAUTHORIZED", "You do not have access to this entry’s space.")

        if space_row.get("status") != "active":
            _log("INVALID_TRANSITION", meta={"spaceStatus": space_row.get("status")})
            return _err("INVALID_TRANSITION", "Space is not active.", spaceStatus=space_row.get("status"))
        if env_row.get("status") != "ready":
            _log("INVALID_TRANSITION", meta={"environmentStatus": env_row.get("status")})
            return _err("INVALID_TRANSITION", "Environment is not ready.", environmentStatus=env_row.get("status"))

        # Validate locale-keyed fields updates
        available_locales = space_row.get("available_locales") or []
        if not isinstance(available_locales, list) or not available_locales:
            _log("VALIDATION_ERROR", meta={"field": "available_locales"})
            return _err("VALIDATION_ERROR", "Space locales are misconfigured.", field="space.available_locales")

        for fid, locmap in fields.items():
            if not isinstance(fid, str) or fid.strip() == "":
                _log("VALIDATION_ERROR", meta={"field": "fields"})
                return _err("VALIDATION_ERROR", "Field keys must be non-empty strings.", field="fields")
            if not isinstance(locmap, dict) or not locmap:
                _log("VALIDATION_ERROR", meta={"field": f"fields.{fid}"})
                return _err("VALIDATION_ERROR", "Each field value must be a non-empty object keyed by locale.", field=f"fields.{fid}")
            for loc in locmap.keys():
                if not isinstance(loc, str) or loc not in available_locales:
                    _log("VALIDATION_ERROR", meta={"field": f"fields.{fid}", "locale": loc})
                    return _err("VALIDATION_ERROR", "Invalid locale key for field.", field=f"fields.{fid}", locale=loc, available_locales=available_locales)

        # Merge at field-id and locale level
        existing_fields = row.get("fields") or {}
        if not isinstance(existing_fields, dict):
            existing_fields = {}

        for fid, locmap in fields.items():
            if fid not in existing_fields or not isinstance(existing_fields.get(fid), dict):
                existing_fields[fid] = {}
            for loc, val in locmap.items():
                existing_fields[fid][loc] = val

        # Increment version and set status changed if previously published
        prev_status = row.get("status")
        prev_sys = row.get("sys_version")
        if not isinstance(prev_sys, int) or prev_sys < 1:
            _log("CONFLICT", meta={"entryId": entryId})
            return _err("CONFLICT", "Entry version is invalid; cannot update safely.", entryId=entryId)

        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        new_status = prev_status
        if prev_status == "published":
            new_status = "changed"
        # keep draft/changed/archived as-is (archived updates are permitted by this tool; no transition rule defined here)

        row["fields"] = existing_fields
        row["sys_version"] = prev_sys + 1
        row["updated_at"] = now
        row["status"] = new_status

        items[idx] = row
        _save("content_items.json", items)

        _log("OK", meta={"entryId": entryId, "sys_version": row["sys_version"], "status": row["status"]})
        return row
    except Exception as e:
        _log("ERROR", meta={"exception": type(e).__name__})
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

def delete_entry(entryId, **_extra):
    import json, os, datetime, time, secrets, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0167000" if __import__("os").path.isdir("./environment_mix/0167000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "delete_entry"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _find_logfile():
        for cand in ("request_logs.json", "usage.json", "audit_logs.json", "api_requests.json"):
            if os.path.exists(os.path.join(_DB, cand)):
                return cand
        return "request_logs.json"
    _LOGF = _find_logfile()

    def _append_log(status, error_code=None, message=None, meta=None):
        try:
            rows = _load(_LOGF)
            if not isinstance(rows, list):
                rows = []
            rows.append({
                "id": "req_" + secrets.token_hex(12),
                "endpoint": endpoint,
                "timestamp": _now(),
                "status": status,
                "error_code": error_code,
                "message": message,
                "latency_ms": int((time.time() - _t0) * 1000),
                "meta": meta or {}
            })
            _save(_LOGF, rows)
        except Exception:
            return

    try:
        if not isinstance(entryId, str) or not re.match(r"^cfl_item_[0-9A-Z]{18,}$", entryId):
            _append_log("VALIDATION_ERROR", "VALIDATION_ERROR", "entryId is invalid.", {"field": "entryId"})
            return _err("VALIDATION_ERROR", "entryId is invalid.", field="entryId")

        items = _load("content_items.json")
        if not isinstance(items, list):
            items = []
        idx = None
        for i, it in enumerate(items):
            if isinstance(it, dict) and it.get("id") == entryId and it.get("type") == "entry":
                idx = i
                break
        if idx is None or items[idx].get("status") == "deleted":
            _append_log("NOT_FOUND", "NOT_FOUND", "Entry not found.", {"entryId": entryId})
            return _err("NOT_FOUND", "Entry not found.", entryId=entryId)

        now = _now()
        row = items[idx]
        row["status"] = "deleted"
        row["deleted_at"] = now
        row["updated_at"] = now
        items[idx] = row
        _save("content_items.json", items)

        _append_log("OK", None, None, {"entryId": entryId})
        return {"entry": row}
    except Exception as e:
        _append_log("VALIDATION_ERROR", "VALIDATION_ERROR", "Unexpected error.", {"detail": str(e)})
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

def publish_entry(entryId=None, entryIds=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0167000" if __import__("os").path.isdir("./environment_mix/0167000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "publish_entry"
    status_code = "ok"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log_request(status, used_credential=None, extra=None):
        logs = _load("request_logs.json")
        row = {
            "id": f"rql_{int(time.time()*1000)}_{os.getpid()}",
            "timestamp": _now(),
            "endpoint": endpoint,
            "credential": used_credential,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if extra:
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    pat = re.compile(r"^cfl_item_[0-9A-Z]{18,}$")

    # Validation: exactly one of entryId, entryIds
    if (entryId is None and entryIds is None) or (entryId is not None and entryIds is not None):
        status_code = "VALIDATION_ERROR"
        _log_request(status_code)
        return _err("VALIDATION_ERROR", "Provide exactly one of entryId or entryIds.")
    ids = None
    single = False
    if entryId is not None:
        if not isinstance(entryId, str) or not pat.match(entryId):
            status_code = "VALIDATION_ERROR"
            _log_request(status_code)
            return _err("VALIDATION_ERROR", "entryId is malformed.", field="entryId")
        ids = [entryId]
        single = True
    else:
        if not isinstance(entryIds, list) or len(entryIds) < 1:
            status_code = "VALIDATION_ERROR"
            _log_request(status_code)
            return _err("VALIDATION_ERROR", "entryIds must be a non-empty array.", field="entryIds")
        if len(entryIds) > 100:
            status_code = "VALIDATION_ERROR"
            _log_request(status_code)
            return _err("VALIDATION_ERROR", "entryIds exceeds maximum batch size of 100.", field="entryIds", max=100)
        for j, x in enumerate(entryIds):
            if not isinstance(x, str) or not pat.match(x):
                status_code = "VALIDATION_ERROR"
                _log_request(status_code)
                return _err("VALIDATION_ERROR", "One or more entryIds are malformed.", field="entryIds", index=j)
        ids = list(entryIds)

    content_items = _load("content_items.json")
    envs = _load("environments.json")
    spaces = _load("spaces.json")

    # Index content items
    by_id = {r.get("id"): (i, r) for i, r in enumerate(content_items)}

    # Bulk operation: atomic per item; return per-item success/failure
    results = []
    any_mutation = False
    now = _now()

    for _id in ids:
        r = {"id": _id}
        if _id not in by_id:
            r["ok"] = False
            r["error"] = _err("NOT_FOUND", "Entry not found.", entryId=_id)["error"]
            results.append(r)
            continue
        idx, item = by_id[_id]
        if item.get("type") != "entry" or item.get("status") == "deleted":
            r["ok"] = False
            r["error"] = _err("NOT_FOUND", "Entry not found.", entryId=_id)["error"]
            results.append(r)
            continue

        env = next((e for e in envs if e.get("id") == item.get("environment_id")), None)
        sp = next((s for s in spaces if env and s.get("id") == env.get("space_id")), None)
        if not env or not sp:
            r["ok"] = False
            r["error"] = _err("NOT_FOUND", "Environment or space not found for entry.",
                              environmentId=item.get("environment_id"), spaceId=(env or {}).get("space_id"))["error"]
            results.append(r)
            continue
        if sp.get("status") != "active" or env.get("status") != "ready":
            r["ok"] = False
            r["error"] = _err("CONFLICT", "Entry cannot be published because its environment is not ready or its space is not active.",
                              spaceStatus=sp.get("status"), environmentStatus=env.get("status"))["error"]
            results.append(r)
            continue

        st = item.get("status")
        if st not in ("draft", "changed"):
            r["ok"] = False
            r["error"] = _err("CONFLICT", "Entry is not eligible to publish in its current state.",
                              entryId=_id, status=st)["error"]
            results.append(r)
            continue

        # Apply publish transition
        new_item = dict(item)
        new_item["published_version"] = int(new_item.get("sys_version") or 1)
        new_item["published_at"] = now
        if not new_item.get("first_published_at"):
            new_item["first_published_at"] = now
        new_item["status"] = "published"
        new_item["updated_at"] = now
        content_items[idx] = new_item
        by_id[_id] = (idx, new_item)
        any_mutation = True

        r["ok"] = True
        r["entry"] = new_item
        results.append(r)

    if any_mutation:
        _save("content_items.json", content_items)

    _log_request("ok" if (single or results) else status_code)

    if single:
        # For single mode, raise NOT_FOUND/CONFLICT like single operation behavior.
        rr = results[0]
        if rr.get("ok"):
            return {"entry": rr["entry"]}
        # If not found -> NOT_FOUND; else conflict
        code = rr["error"].get("code") if isinstance(rr.get("error"), dict) else "CONFLICT"
        return {"error": rr["error"]} if code else _err("CONFLICT", "Publish failed.")
    else:
        return {
            "results": results,
            "summary": {
                "requested": len(ids),
                "succeeded": sum(1 for r in results if r.get("ok")),
                "failed": sum(1 for r in results if not r.get("ok")),
            },
        }

