def list_assets(spaceId=None, environmentId=None, limit=None, skip=None, order=None, **_extra):
    import json, os, datetime, time, secrets, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0167000" if __import__("os").path.isdir("./environment_mix/0167000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "list_assets"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _find_logfile():
        for cand in ("request_logs.json", "usage.json", "audit_logs.json", "api_requests.json"):
            if os.path.exists(os.path.join(_DB, cand)):
                return cand
        return "request_logs.json"
    _LOGF = _find_logfile()

    def _append_log(status, error_code=None, message=None, meta=None):
        try:
            rows = _load(_LOGF)
            if not isinstance(rows, list):
                rows = []
            rec = {
                "id": "req_" + secrets.token_hex(12),
                "endpoint": endpoint,
                "timestamp": _now(),
                "status": status,
                "latency_ms": int((time.time() - _t0) * 1000),
            }
            if error_code is not None:
                rec["error_code"] = error_code
            if message is not None:
                rec["message"] = message
            if meta is not None:
                rec["meta"] = meta
            rows.append(rec)
            _save(_LOGF, rows)
        except Exception:
            return

    try:
        if spaceId is not None and (not isinstance(spaceId, str) or not re.match(r"^cfl_space_[0-9A-Z]{18,}$", spaceId)):
            _append_log("VALIDATION_ERROR", "VALIDATION_ERROR", "spaceId is invalid.", {"field": "spaceId"})
            return _err("VALIDATION_ERROR", "spaceId is invalid.", field="spaceId")
        if environmentId is not None and (not isinstance(environmentId, str) or not re.match(r"^cfl_env_[0-9A-Z]{18,}$", environmentId)):
            _append_log("VALIDATION_ERROR", "VALIDATION_ERROR", "environmentId is invalid.", {"field": "environmentId"})
            return _err("VALIDATION_ERROR", "environmentId is invalid.", field="environmentId")

        if limit is None:
            limit = 3
        if skip is None:
            skip = 0
        if not isinstance(limit, int) or limit < 1:
            _append_log("VALIDATION_ERROR", "VALIDATION_ERROR", "limit is invalid.", {"field": "limit"})
            return _err("VALIDATION_ERROR", "limit is invalid.", field="limit")
        if limit > 3:
            limit = 3  # service-enforced cap for this tool
        if not isinstance(skip, int) or skip < 0:
            _append_log("VALIDATION_ERROR", "VALIDATION_ERROR", "skip is invalid.", {"field": "skip"})
            return _err("VALIDATION_ERROR", "skip is invalid.", field="skip")

        allowed_orders = {"updated_at", "-updated_at", "created_at", "-created_at"}
        if order is None:
            order = "-updated_at"
        if not isinstance(order, str):
            _append_log("VALIDATION_ERROR", "VALIDATION_ERROR", "order is invalid.", {"field": "order", "allowed": sorted(list(allowed_orders))})
            return _err("VALIDATION_ERROR", "order is invalid.", field="order", allowed=sorted(list(allowed_orders)))
        if order not in allowed_orders:
            _append_log("VALIDATION_ERROR", "VALIDATION_ERROR", "order is invalid.", {"field": "order", "allowed": sorted(list(allowed_orders))})
            return _err("VALIDATION_ERROR", "order is invalid.", field="order", allowed=sorted(list(allowed_orders)))

        envs = _load("environments.json")
        if not isinstance(envs, list):
            envs = []
        spaces = _load("spaces.json")
        if not isinstance(spaces, list):
            spaces = []

        # Reference validation: if provided, must exist and match.
        env = None
        if environmentId is not None:
            env = next((e for e in envs if isinstance(e, dict) and e.get("id") == environmentId), None)
            if env is None:
                _append_log("NOT_FOUND", "NOT_FOUND", "Environment not found.", {"environmentId": environmentId})
                return _err("NOT_FOUND", "Environment not found.", environmentId=environmentId)

        space = None
        if spaceId is not None:
            space = next((s for s in spaces if isinstance(s, dict) and s.get("id") == spaceId), None)
            if space is None:
                _append_log("NOT_FOUND", "NOT_FOUND", "Space not found.", {"spaceId": spaceId})
                return _err("NOT_FOUND", "Space not found.", spaceId=spaceId)

        if env is not None and space is not None and env.get("space_id") != space.get("id"):
            _append_log("UNAUTHORIZED", "UNAUTHORIZED", "Environment does not belong to space.", {"spaceId": spaceId, "environmentId": environmentId})
            return _err("UNAUTHORIZED", "Environment does not belong to space.", spaceId=spaceId, environmentId=environmentId)

        # Business rule: must be scoped; if missing, pick a working env/space combo.
        if env is None:
            # choose any ready env whose space active, optionally matching spaceId
            for e in envs:
                if not isinstance(e, dict):
                    continue
                if e.get("status") != "ready":
                    continue
                sp = next((s for s in spaces if isinstance(s, dict) and s.get("id") == e.get("space_id")), None)
                if not sp or sp.get("status") != "active":
                    continue
                if space is not None and sp.get("id") != space.get("id"):
                    continue
                env = e
                space = sp
                break
            if env is None:
                _append_log("UNAUTHORIZED", "UNAUTHORIZED", "No accessible ready environment found.", {})
                return _err("UNAUTHORIZED", "No accessible ready environment found.")
        else:
            if space is None:
                space = next((s for s in spaces if isinstance(s, dict) and s.get("id") == env.get("space_id")), None)
            if not space or space.get("status") != "active":
                _append_log("UNAUTHORIZED", "UNAUTHORIZED", "Space is not active.", {"spaceId": env.get("space_id")})
                return _err("UNAUTHORIZED", "Space is not active.", spaceId=env.get("space_id"))
            if env.get("status") != "ready":
                _append_log("INVALID_TRANSITION", "INVALID_TRANSITION", "Environment is not ready.", {"environmentId": env.get("id"), "status": env.get("status")})
                return _err("INVALID_TRANSITION", "Environment is not ready.", environmentId=env.get("id"), status=env.get("status"))

        items = _load("content_items.json")
        if not isinstance(items, list):
            items = []

        rows = [it for it in items if isinstance(it, dict)
                and it.get("type") == "asset"
                and it.get("status") != "deleted"
                and it.get("environment_id") == env.get("id")]

        key = order.lstrip("-")
        reverse = order.startswith("-")
        def _k(r):
            v = r.get(key)
            return v if isinstance(v, str) else ""
        rows.sort(key=_k, reverse=reverse)

        total = len(rows)
        page = rows[skip:skip + limit]
        has_more = (skip + limit) < total

        _append_log("OK", None, None, {"spaceId": space.get("id") if space else None, "environmentId": env.get("id") if env else None, "count": len(page), "total": total})
        return {
            "items": page,
            "total": total,
            "skip": skip,
            "limit": limit,
            "has_more": has_more
        }
    except Exception as e:
        _append_log("VALIDATION_ERROR", "VALIDATION_ERROR", "Unexpected error.", {"detail": str(e)})
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

