def update_asset(asset_id, fields=None, asset_meta=None, sys_version=None, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0167000" if __import__("os").path.isdir("./environment_mix/0167000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, message=None, **extra):
        logs = _load("request_logs.json")
        row = {
            "id": "req_" + secrets.token_hex(12),
            "tool": "update_asset",
            "ts": now,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if message is not None:
            row["message"] = message
        row.update(extra or {})
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits():
        rl = _load("rate_limits.json")
        if not rl:
            return None
        rule = None
        for r in rl:
            if r.get("tool") in (None, "", "update_asset"):
                rule = r
                break
        if not rule:
            return None
        window_s = int(rule.get("window_seconds") or 60)
        max_req = int(rule.get("max_requests") or 0)
        if max_req <= 0:
            return None
        logs = _load("request_logs.json")
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)
        def _parse(ts):
            try:
                if ts.endswith("Z"):
                    ts = ts[:-1]
                return datetime.datetime.fromisoformat(ts)
            except Exception:
                return None
        cnt = 0
        for e in logs:
            if e.get("tool") != "update_asset":
                continue
            dt = _parse(e.get("ts", ""))
            if dt and dt >= cutoff:
                cnt += 1
        if cnt >= max_req:
            return _err("RATE_LIMIT", "Rate limit exceeded", window_seconds=window_s, max_requests=max_req)
        return None

    limit_err = _enforce_limits()
    if limit_err:
        _log("error", limit_err["error"]["message"], error=limit_err["error"])
        return limit_err

    if not isinstance(asset_id, str) or not re.match(r"^cfl_item_[0-9A-Z]{18,}$", asset_id):
        e = _err("VALIDATION_ERROR", "asset_id is malformed", field="asset_id")
        _log("error", e["error"]["message"], error=e["error"])
        return e
    if fields is not None and not isinstance(fields, dict):
        e = _err("VALIDATION_ERROR", "fields must be an object", field="fields")
        _log("error", e["error"]["message"], error=e["error"])
        return e
    if asset_meta is not None and not isinstance(asset_meta, dict):
        e = _err("VALIDATION_ERROR", "asset_meta must be an object", field="asset_meta")
        _log("error", e["error"]["message"], error=e["error"])
        return e
    if sys_version is not None:
        if not isinstance(sys_version, int) or sys_version < 0:
            e = _err("VALIDATION_ERROR", "sys_version must be a non-negative integer", field="sys_version")
            _log("error", e["error"]["message"], error=e["error"])
            return e

    if fields is None and asset_meta is None:
        e = _err("VALIDATION_ERROR", "At least one of fields or asset_meta must be provided")
        _log("error", e["error"]["message"], error=e["error"])
        return e

    items = _load("content_items.json")
    envs = _load("environments.json")
    spaces = _load("spaces.json")

    idx = None
    for i, r in enumerate(items):
        if r.get("id") == asset_id and r.get("type") == "asset":
            idx = i
            break
    if idx is None or items[idx].get("status") == "deleted":
        e = _err("NOT_FOUND", "Asset not found", asset_id=asset_id)
        _log("error", e["error"]["message"], error=e["error"])
        return e

    asset = items[idx]
    env = next((e for e in envs if e.get("id") == asset.get("environment_id")), None)
    if not env or env.get("status") != "ready":
        e = _err("UNAUTHORIZED", "Environment is not ready or not accessible")
        _log("error", e["error"]["message"], error=e["error"], asset_id=asset_id)
        return e
    space = next((s for s in spaces if s.get("id") == env.get("space_id")), None)
    if not space or space.get("status") != "active":
        e = _err("UNAUTHORIZED", "Space is not active or not accessible")
        _log("error", e["error"]["message"], error=e["error"], asset_id=asset_id)
        return e

    if sys_version is not None and int(asset.get("sys_version") or 0) != sys_version:
        e = _err("CONFLICT", "VERSION_MISMATCH", current_sys_version=asset.get("sys_version"), provided_sys_version=sys_version)
        _log("error", e["error"]["message"], error=e["error"], asset_id=asset_id)
        return e

    available_locales = space.get("available_locales") or []
    if fields is not None:
        for fid, v in fields.items():
            if not isinstance(fid, str) or fid.strip() == "":
                e = _err("VALIDATION_ERROR", "Field ids must be non-empty strings", field_id=fid)
                _log("error", e["error"]["message"], error=e["error"])
                return e
            if not isinstance(v, dict):
                e = _err("VALIDATION_ERROR", "Each field value must be an object keyed by locale", field=fid)
                _log("error", e["error"]["message"], error=e["error"])
                return e
            if len(v) == 0:
                e = _err("VALIDATION_ERROR", "Field value must include locale keys", field=fid)
                _log("error", e["error"]["message"], error=e["error"])
                return e
            for loc in v.keys():
                if loc not in available_locales:
                    e = _err("VALIDATION_ERROR", "Unsupported locale key for this space", field=fid, locale=loc)
                    _log("error", e["error"]["message"], error=e["error"])
                    return e

    # Apply updates (merge fields at field-id and locale level)
    if fields is not None:
        current = asset.get("fields") or {}
        if not isinstance(current, dict):
            current = {}
        for fid, locale_map in fields.items():
            existing_locale_map = current.get(fid)
            if not isinstance(existing_locale_map, dict):
                existing_locale_map = {}
            for loc, val in locale_map.items():
                existing_locale_map[loc] = val
            current[fid] = existing_locale_map
        asset["fields"] = current

    if asset_meta is not None:
        asset["asset_meta"] = asset_meta

    asset["sys_version"] = int(asset.get("sys_version") or 0) + 1
    asset["updated_at"] = now
    # For assets, align with entry behavior: if previously published, mark changed on update
    if asset.get("status") == "published":
        asset["status"] = "changed"

    items[idx] = asset
    _save("content_items.json", items)

    resp = {"asset": asset, "meta": {"environment_id": env.get("id"), "space_id": space.get("id")}}
    _log("ok", asset_id=asset_id, environment_id=env.get("id"))
    return resp

