def publish_asset(asset_id, sys_version=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0167000" if __import__("os").path.isdir("./environment_mix/0167000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- usage / rate limit logging (best-effort if collection exists) ----
    def _log(status_code, message=None, credential_id=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": "publish_asset",
            "credential_id": credential_id,
            "status": status_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        }
        if extra is not None:
            row["extra"] = extra
        logs.append(row)
        try:
            _save("request_logs.json", logs)
        except Exception:
            pass

    # ---- validation ----
    if not isinstance(asset_id, str) or not re.match(r"^cfl_item_[0-9A-Z]{18,}$", asset_id):
        _log("VALIDATION_ERROR", "asset_id is malformed")
        return _err("VALIDATION_ERROR", "asset_id is malformed", field="asset_id")
    if sys_version is not None:
        if not isinstance(sys_version, int) or sys_version < 0:
            _log("VALIDATION_ERROR", "sys_version is invalid")
            return _err("VALIDATION_ERROR", "sys_version is invalid", field="sys_version")

    # ---- load data ----
    items = _load("content_items.json")
    envs = _load("environments.json")
    spaces = _load("spaces.json")

    if not isinstance(items, list):
        items = []
    if not isinstance(envs, list):
        envs = []
    if not isinstance(spaces, list):
        spaces = []

    # ---- find asset (by upstream id) ----
    asset = None
    for it in items:
        if isinstance(it, dict) and it.get("type") == "asset" and it.get("contentful_item_id") == asset_id:
            asset = it
            break

    if not asset or asset.get("status") == "deleted":
        _log("NOT_FOUND", "Asset not found")
        return _err("NOT_FOUND", "Asset does not exist or has been deleted")

    # ---- scope checks: environment ready + parent space active ----
    env = None
    for e in envs:
        if isinstance(e, dict) and e.get("id") == asset.get("environment_id"):
            env = e
            break
    if not env:
        _log("UNAUTHORIZED", "No authorized environment found for asset")
        return _err("UNAUTHORIZED", "Not authorized for this operation")

    sp = None
    for s in spaces:
        if isinstance(s, dict) and s.get("id") == env.get("space_id"):
            sp = s
            break

    if not sp or sp.get("status") != "active" or env.get("status") != "ready":
        _log("UNAUTHORIZED", "Environment/space not in active/ready state")
        return _err("UNAUTHORIZED", "Not authorized for this operation")

    # ---- optimistic concurrency ----
    cur_ver = asset.get("sys_version")
    if not isinstance(cur_ver, int):
        _log("VALIDATION_ERROR", "Asset sys_version is corrupted")
        return _err("VALIDATION_ERROR", "Asset sys metadata is invalid")
    if sys_version is not None and sys_version != cur_ver:
        _log("CONFLICT", "Version mismatch", extra={"current_version": cur_ver})
        return _err("CONFLICT", "VERSION_MISMATCH: sys_version does not match current version", current_version=cur_ver)

    # ---- transition rules ----
    if asset.get("status") == "published":
        _log("CONFLICT", "Asset already published")
        return _err("CONFLICT", "Asset is already published")
    if asset.get("status") not in ("draft", "changed"):
        _log("INVALID_TRANSITION", "Asset cannot be published from current status", extra={"status": asset.get("status")})
        return _err("INVALID_TRANSITION", "Asset cannot be published from its current status", from_status=asset.get("status"))

    # ---- apply publish ----
    # Contentful-like: publish sets published_version=sys_version and status=published; timestamps set.
    asset["published_version"] = cur_ver
    asset["published_at"] = now
    if not asset.get("first_published_at"):
        asset["first_published_at"] = now
    asset["status"] = "published"
    asset["updated_at"] = now

    try:
        _save("content_items.json", items)
    except Exception as e:
        _log("CONFLICT", "Failed to persist changes")
        return _err("CONFLICT", "Failed to persist changes", detail=str(e))

    _log("OK")
    return {"asset": asset}

def unpublish_asset(asset_id, sys_version=None, **_extra):
