        row = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": "unpublish_asset",
            "credential_id": credential_id,
            "status": status_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        }
        if extra is not None:
            row["extra"] = extra
        logs.append(row)
        try:
            _save("request_logs.json", logs)
        except Exception:
            pass

    if not isinstance(asset_id, str) or not re.match(r"^cfl_item_[0-9A-Z]{18,}$", asset_id):
        _log("VALIDATION_ERROR", "asset_id is malformed")
        return _err("VALIDATION_ERROR", "asset_id is malformed", field="asset_id")
    if sys_version is not None:
        if not isinstance(sys_version, int) or sys_version < 0:
            _log("VALIDATION_ERROR", "sys_version is invalid")
            return _err("VALIDATION_ERROR", "sys_version is invalid", field="sys_version")

    items = _load("content_items.json")
    envs = _load("environments.json")
    spaces = _load("spaces.json")

    if not isinstance(items, list):
        items = []
    if not isinstance(envs, list):
        envs = []
    if not isinstance(spaces, list):
        spaces = []

    asset = None
    for it in items:
        if isinstance(it, dict) and it.get("type") == "asset" and it.get("contentful_item_id") == asset_id:
            asset = it
            break

    if not asset or asset.get("status") == "deleted":
        _log("NOT_FOUND", "Asset not found")
        return _err("NOT_FOUND", "Asset does not exist or has been deleted")

    env = None
    for e in envs:
        if isinstance(e, dict) and e.get("id") == asset.get("environment_id"):
            env = e
            break
    if not env:
        _log("UNAUTHORIZED", "No authorized environment found for asset")
        return _err("UNAUTHORIZED", "Not authorized for this operation")

    sp = None
    for s in spaces:
        if isinstance(s, dict) and s.get("id") == env.get("space_id"):
            sp = s
            break
    if not sp or sp.get("status") != "active" or env.get("status") != "ready":
        _log("UNAUTHORIZED", "Environment/space not in active/ready state")
        return _err("UNAUTHORIZED", "Not authorized for this operation")

    cur_ver = asset.get("sys_version")
    if not isinstance(cur_ver, int):
        _log("VALIDATION_ERROR", "Asset sys_version is corrupted")
        return _err("VALIDATION_ERROR", "Asset sys metadata is invalid")
    if sys_version is not None and sys_version != cur_ver:
        _log("CONFLICT", "Version mismatch", extra={"current_version": cur_ver})
        return _err("CONFLICT", "VERSION_MISMATCH: sys_version does not match current version", current_version=cur_ver)

    if asset.get("status") != "published":
        _log("CONFLICT", "Asset not published", extra={"status": asset.get("status")})
        return _err("CONFLICT", "Asset is not currently published")

    # Business rule: unpublish allowed only from published; set status='draft' (or 'changed' if unpublished changes).
    # This datastore doesn't track a separate "has_unpublished_changes" flag; if sys_version > published_version treat as changed.
    pv = asset.get("published_version")
    if isinstance(pv, int) and cur_ver > pv:
        new_status = "changed"
    else:
        new_status = "draft"
    asset["status"] = new_status
    asset["updated_at"] = now
    # published_at remains last published timestamp; published_version left as-is (historic last publish)

    try:
        _save("content_items.json", items)
    except Exception as e:
        _log("CONFLICT", "Failed to persist changes")
        return _err("CONFLICT", "Failed to persist changes", detail=str(e))

    _log("OK")
    return {"asset": asset}

