        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, message=None, credential_id=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": "list_content_types",
            "credential_id": credential_id,
            "status": status_code,
            "message": message,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now,
        }
        if extra is not None:
            row["extra"] = extra
        logs.append(row)
        try:
            _save("request_logs.json", logs)
        except Exception:
            pass

    if not isinstance(space_id, str) or not re.match(r"^cfl_space_[0-9A-Z]{18,}$", space_id):
        _log("VALIDATION_ERROR", "space_id is malformed")
        return _err("VALIDATION_ERROR", "space_id is malformed", field="space_id")
    if environment_id is not None:
        if not isinstance(environment_id, str) or not re.match(r"^cfl_env_[0-9A-Z]{18,}$", environment_id):
            _log("VALIDATION_ERROR", "environment_id is malformed")
            return _err("VALIDATION_ERROR", "environment_id is malformed", field="environment_id")
    if skip is None:
        skip = 0
    if not isinstance(skip, int) or skip < 0:
        _log("VALIDATION_ERROR", "skip must be a non-negative integer")
        return _err("VALIDATION_ERROR", "skip must be a non-negative integer", field="skip")

    spaces = _load("spaces.json")
    envs = _load("environments.json")
    cts = _load("content_types.json")

    if not isinstance(spaces, list):
        spaces = []
    if not isinstance(envs, list):
        envs = []
    if not isinstance(cts, list):
        cts = []

    # Resolve space by upstream contentful_space_id
    space = None
    for s in spaces:
        if isinstance(s, dict) and s.get("contentful_space_id") == space_id:
            space = s
            break
    if not space or space.get("status") == "deleted":
        _log("NOT_FOUND", "Space not found")
        return _err("NOT_FOUND", "Space does not exist")

    # If environment provided, resolve it within space
    env = None
    if environment_id is not None:
        for e in envs:
            if isinstance(e, dict) and e.get("contentful_environment_id") == environment_id and e.get("space_id") == space.get("id"):
                env = e
                break
        if not env or env.get("status") == "deleted":
            _log("NOT_FOUND", "Environment not found in space")
            return _err("NOT_FOUND", "Environment does not exist within the given space")

    # Collect content types (exclude deleted)
    rows = []
    if env is not None:
        for ct in cts:
            if isinstance(ct, dict) and ct.get("environment_id") == env.get("id") and ct.get("status") != "deleted":
                rows.append(ct)
    else:
        # across space: include ct whose environment belongs to space
        env_ids = set()
        for e in envs:
            if isinstance(e, dict) and e.get("space_id") == space.get("id") and e.get("status") != "deleted":
                env_ids.add(e.get("id"))
        for ct in cts:
            if isinstance(ct, dict) and ct.get("environment_id") in env_ids and ct.get("status") != "deleted":
                rows.append(ct)

    # Sort by updated_at desc (fallback created_at)
    def _key(x):
        ua = x.get("updated_at") or x.get("created_at") or ""
        return ua
    rows.sort(key=_key, reverse=True)

    limit = 10
    total = len(rows)
    page = rows[skip:skip + limit]
    has_more = (skip + limit) < total
    next_skip = (skip + limit) if has_more else None

    _log("OK", extra={"total": total, "returned": len(page), "skip": skip, "limit": limit})
    return {
        "items": page,
        "total": total,
        "skip": skip,
        "limit": limit,
        "has_more": has_more,
        "next_cursor": next_skip
    }

