        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "get_content_type"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _find_logfile():
        for cand in ("request_logs.json", "usage.json", "audit_logs.json", "api_requests.json"):
            if os.path.exists(os.path.join(_DB, cand)):
                return cand
        return "request_logs.json"

    _LOGF = _find_logfile()

    def _read_logs():
        logs = _load(_LOGF)
        return logs if isinstance(logs, list) else []

    def _write_log(status, error_code=None, message=None, scope=None):
        logs = _read_logs()
        rec = {
            "id": "req_" + secrets.token_hex(12),
            "endpoint": endpoint,
            "timestamp": _now(),
            "status": status,
            "latency_ms": int((time.time() - _t0) * 1000),
        }
        if message is not None:
            rec["message"] = message
        meta = {}
        if scope is not None:
            meta["scope"] = scope
        if meta:
            rec["meta"] = meta
        if error_code is not None:
            rec["error_code"] = error_code
        logs.append(rec)
        _save(_LOGF, logs)

    def _rate_limit_check(scope):
        limits = _load("rate_limits.json")
        if not isinstance(limits, list):
            return None
        rule = None
        for r in limits:
            if isinstance(r, dict) and (r.get("endpoint") == endpoint or r.get("tool") == endpoint):
                rule = r
                break
        if not rule:
            return None
        try:
            if rule.get("per_minute") is not None:
                window = 60
                limit = int(rule.get("per_minute"))
            else:
                window = int(rule.get("window_seconds") or 60)
                limit = int(rule.get("max_requests") or 0)
        except Exception:
            return None
        if limit <= 0:
            return None
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window)
        cnt = 0
        for e in _read_logs():
            if not isinstance(e, dict):
                continue
            if (e.get("endpoint") or e.get("tool")) != endpoint:
                continue
            meta = e.get("meta") or {}
            if scope is not None and meta.get("scope") != scope:
                continue
            ts = _parse_ts(e.get("timestamp") or e.get("ts") or e.get("created_at"))
            if ts and ts >= cutoff:
                cnt += 1
        if cnt >= limit:
            return _err("RATE_LIMIT", "Rate limit exceeded", window_seconds=window, max_requests=limit)
        return None

    if not isinstance(content_type_id, str) or content_type_id.strip() == "":
        e = _err("VALIDATION_ERROR", "content_type_id must be a non-empty string.", field="content_type_id")
        _write_log("error", error_code=e["error"]["code"], message=e["error"]["message"])
        return e

    rl = _rate_limit_check(None)
    if rl:
        _write_log("error", error_code=rl["error"]["code"], message=rl["error"]["message"])
        return rl

    cts = _load("content_types.json")
    envs = _load("environments.json")
    spaces = _load("spaces.json")
    if not isinstance(cts, list): cts = []
    if not isinstance(envs, list): envs = []
    if not isinstance(spaces, list): spaces = []

    # Correct lookup: by internal id
    ct = next((row for row in cts if isinstance(row, dict) and row.get("id") == content_type_id), None)
    if not ct or ct.get("status") == "deleted":
        e = _err("NOT_FOUND", "Content Type does not exist or has been deleted.", content_type_id=content_type_id)
        _write_log("error", error_code=e["error"]["code"], message=e["error"]["message"])
        return e

    env = next((e for e in envs if isinstance(e, dict) and e.get("id") == ct.get("environment_id")), None)
    if not env:
        e = _err("NOT_FOUND", "Environment not found for content type.", environment_id=ct.get("environment_id"))
        _write_log("error", error_code=e["error"]["code"], message=e["error"]["message"], scope=ct.get("environment_id"))
        return e
    space = next((s for s in spaces if isinstance(s, dict) and s.get("id") == env.get("space_id")), None)
    if not space:
        e = _err("NOT_FOUND", "Parent space not found for content type.", space_id=env.get("space_id"))
        _write_log("error", error_code=e["error"]["code"], message=e["error"]["message"], scope=env.get("id"))
        return e

    if space.get("status") != "active" or env.get("status") != "ready":
        e = _err("UNAUTHORIZED", "You do not have access to this content type in the current scope.", space_status=space.get("status"), environment_status=env.get("status"))
        _write_log("error", error_code=e["error"]["code"], message=e["error"]["message"], scope=env.get("id"))
        return e

    _write_log("ok", scope=env.get("id"))
    return {"content_type": ct}

