            ts = _parse_ts(e.get("timestamp") or e.get("ts") or e.get("created_at"))
            if ts and ts >= cutoff:
                cnt += 1
        if cnt >= limit:
            return _err("RATE_LIMIT", "Rate limit exceeded", window_seconds=window, max_requests=limit)
        return None

    # Validation (relaxed patterns but strict types)
    if not isinstance(environment_id, str) or environment_id.strip() == "":
        e = _err("VALIDATION_ERROR", "environment_id must be a non-empty string.", field="environment_id")
        _write_log("error", error_code=e["error"]["code"], message=e["error"]["message"], scope=environment_id if isinstance(environment_id, str) else None)
        return e
