        return e
    if display_field is not None and not isinstance(display_field, str):
        e = _err("VALIDATION_ERROR", "display_field must be a string when provided.", field="display_field")
        _write_log("error", error_code=e["error"]["code"], message=e["error"]["message"], scope=environment_id)
        return e

    rl = _rate_limit_check(environment_id)
    if rl:
        _write_log("error", error_code=rl["error"]["code"], message=rl["error"]["message"], scope=environment_id)
        return rl

    envs = _load("environments.json")
    spaces = _load("spaces.json")
    cts = _load("content_types.json")
    if not isinstance(envs, list): envs = []
    if not isinstance(spaces, list): spaces = []
    if not isinstance(cts, list): cts = []

    env = next((e for e in envs if isinstance(e, dict) and e.get("id") == environment_id), None)
    if not env:
        e = _err("NOT_FOUND", "Environment does not exist.", environment_id=environment_id)
        _write_log("error", error_code=e["error"]["code"], message=e["error"]["message"], scope=environment_id)
        return e
    space = next((s for s in spaces if isinstance(s, dict) and s.get("id") == env.get("space_id")), None)
