        e = _err("NOT_FOUND", "Parent space does not exist.", space_id=env.get("space_id"))
        _write_log("error", error_code=e["error"]["code"], message=e["error"]["message"], scope=environment_id)
        return e
    if space.get("status") != "active" or env.get("status") != "ready":
        e = _err("INVALID_TRANSITION", "Environment must be ready and its space must be active.", space_status=space.get("status"), environment_status=env.get("status"))
        _write_log("error", error_code=e["error"]["code"], message=e["error"]["message"], scope=environment_id)
        return e

    # Validate display_field refers to a field in schema (if provided)
    field_ids = set()
    if isinstance(fields_schema.get("fields"), list):
        for f in fields_schema["fields"]:
            if isinstance(f, dict) and isinstance(f.get("id"), str):
                field_ids.add(f["id"])
    if display_field is not None and field_ids and display_field not in field_ids:
        e = _err("VALIDATION_ERROR", "display_field must refer to a field id in fields_schema.", field="display_field")
        _write_log("error", error_code=e["error"]["code"], message=e["error"]["message"], scope=environment_id)
        return e

    # Unique(environment_id, contentful_content_type_id) if provided; otherwise generate a unique external id
    if contentful_content_type_id is not None:
        if any(isinstance(r, dict) and r.get("environment_id") == environment_id and r.get("contentful_content_type_id") == contentful_content_type_id for r in cts if r.get("status") != "deleted"):
            e = _err("CONFLICT", "A content type with the same contentful_content_type_id already exists in this environment.", contentful_content_type_id=contentful_content_type_id)
            _write_log("error", error_code=e["error"]["code"], message=e["error"]["message"], scope=environment_id)
            return e
        ext_id = contentful_content_type_id
    else:
        ext_id = "ct_" + secrets.token_hex(8)

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "".join(secrets.choice(alphabet) for _ in range(20))

    now = _now()
    new_ct = {
        "id": _new_id("cfl_ct_"),
        "environment_id": environment_id,
        "contentful_content_type_id": ext_id,
        "name": name,
        "description": description,
        "display_field": display_field,
        "fields_schema": fields_schema,
        "sys_version": 1,
        "published_version": None,
        "status": "draft",
        "created_at": now,
        "updated_at": now,
    }

    cts.append(new_ct)
    _save("content_types.json", cts)
    _write_log("ok", scope=environment_id)
    return {"content_type": new_ct}

def update_content_type(content_type_id, contentful_content_type_id=None, name=None, description=None, display_field=None, fields_schema=None, sys_version=None, **_extra):
    import json, os, datetime, re, time, random, copy

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0167000" if __import__("os").path.isdir("./environment_mix/0167000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "update_content_type"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, credential_used=None, error=None):
        logs = _load("request_logs.json")
        row = {
            "id": f"req_{int(time.time()*1000)}_{random.randint(1000,9999)}",
            "endpoint": endpoint,
            "credential_used": credential_used,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now()
        }
        if error is not None:
            row["error"] = error
        logs.append(row)
        _save("request_logs.json", logs)

    try:
        if not isinstance(content_type_id, str) or not re.match(r"^cfl_ct_[0-9A-HJKMNP-TV-Z]{18,}$", content_type_id):
            e = _err("VALIDATION_ERROR", "content_type_id is malformed.", field="content_type_id")
            _log("error", error=e["error"])
            return e
        if contentful_content_type_id is not None and not isinstance(contentful_content_type_id, str):
            e = _err("VALIDATION_ERROR", "contentful_content_type_id must be a string.", field="contentful_content_type_id")
            _log("error", error=e["error"])
            return e
        if name is not None and (not isinstance(name, str) or name.strip() == ""):
            e = _err("VALIDATION_ERROR", "name must be a non-empty string when provided.", field="name")
            _log("error", error=e["error"])
            return e
        if description is not None and not isinstance(description, str):
            e = _err("VALIDATION_ERROR", "description must be a string.", field="description")
            _log("error", error=e["error"])
            return e
        if display_field is not None and not isinstance(display_field, str):
            e = _err("VALIDATION_ERROR", "display_field must be a string.", field="display_field")
            _log("error", error=e["error"])
            return e
        if fields_schema is not None and not isinstance(fields_schema, dict):
            e = _err("VALIDATION_ERROR", "fields_schema must be an object when provided.", field="fields_schema")
            _log("error", error=e["error"])
            return e
        if sys_version is not None and not isinstance(sys_version, int):
            e = _err("VALIDATION_ERROR", "sys_version must be an integer when provided.", field="sys_version")
            _log("error", error=e["error"])
            return e

        cts = _load("content_types.json")
        envs = _load("environments.json")
        spaces = _load("spaces.json")

        idx = next((i for i, x in enumerate(cts) if x.get("id") == content_type_id), None)
        if idx is None:
            e = _err("NOT_FOUND", "Content Type not found.", content_type_id=content_type_id)
            _log("error", error=e["error"])
            return e

        ct = cts[idx]
        if ct.get("status") == "deleted":
            e = _err("NOT_FOUND", "Content Type is deleted.", content_type_id=content_type_id)
            _log("error", error=e["error"])
            return e

        env = next((x for x in envs if x.get("id") == ct.get("environment_id")), None)
        space = next((s for s in spaces if s.get("id") == (env.get("space_id") if env else None)), None)
        if env is None or space is None or space.get("status") != "active" or env.get("status") != "ready":
            e = _err("UNAUTHORIZED", "No accessible active space/ready environment combination can serve this request.")
            _log("error", error=e["error"])
            return e

        # Optimistic locking if provided
        if sys_version is not None and sys_version != ct.get("sys_version"):
            e = _err("CONFLICT", "sys_version does not match current version.", expected=ct.get("sys_version"), provided=sys_version)
            _log("error", error=e["error"])
            return e

        merged = copy.deepcopy(ct)

        # Merge semantics: scalar props replace; fields_schema deep-merge dict keys
        if contentful_content_type_id is not None:
            # enforce unique(environment_id, contentful_content_type_id)
            for other in cts:
                if other.get("id") != content_type_id and other.get("environment_id") == merged.get("environment_id") and other.get("contentful_content_type_id") == contentful_content_type_id:
                    e = _err("CONFLICT", "A Content Type with this contentful_content_type_id already exists in the environment.",
                             contentful_content_type_id=contentful_content_type_id)
                    _log("error", error=e["error"])
                    return e
            merged["contentful_content_type_id"] = contentful_content_type_id
        if name is not None:
            merged["name"] = name
        if description is not None:
            merged["description"] = description
        if fields_schema is not None:
            def _deep_merge(a, b):
                if not isinstance(a, dict) or not isinstance(b, dict):
                    return copy.deepcopy(b)
                out = copy.deepcopy(a)
                for k, v in b.items():
                    if k in out and isinstance(out[k], dict) and isinstance(v, dict):
                        out[k] = _deep_merge(out[k], v)
                    else:
                        out[k] = copy.deepcopy(v)
                return out
            merged["fields_schema"] = _deep_merge(merged.get("fields_schema") or {}, fields_schema)

        if display_field is not None:
            merged["display_field"] = display_field

        # Validate display_field exists in resulting schema (if set)
        schema = merged.get("fields_schema") or {}
        fields_list = schema.get("fields")
        if fields_list is None:
            fields_list = []
        if not isinstance(fields_list, list):
            e = _err("VALIDATION_ERROR", "Resulting fields_schema.fields must be an array.", field="fields_schema.fields")
            _log("error", error=e["error"])
            return e
        field_ids = set()
        for i, f in enumerate(fields_list):
            if not isinstance(f, dict):
                e = _err("VALIDATION_ERROR", "Each field definition must be an object.", field=f"fields_schema.fields[{i}]")
                _log("error", error=e["error"])
                return e
            fid = f.get("id")
            if not isinstance(fid, str) or fid.strip() == "":
                e = _err("VALIDATION_ERROR", "Each field must have a non-empty string id.", field=f"fields_schema.fields[{i}].id")
                _log("error", error=e["error"])
                return e
            field_ids.add(fid)

        if merged.get("display_field") is not None and merged.get("display_field") not in field_ids:
            e = _err("VALIDATION_ERROR", "display_field must refer to a field id present in the resulting fields_schema.", field="display_field")
            _log("error", error=e["error"])
            return e

        # Apply sys_version increment; business rule: updating published sets status to draft
        merged["sys_version"] = int(merged.get("sys_version") or 0) + 1
        if merged["sys_version"] < 1:
            merged["sys_version"] = 1

        if ct.get("status") == "published":
            merged["status"] = "draft"
            # published_version must be <= sys_version; keep as-is (<= previous sys_version), still <= new sys_version
        merged["updated_at"] = _now()

        cts[idx] = merged
        _save("content_types.json", cts)
        _log("ok")
        return {"content_type": merged}
    except Exception as ex:
        e = _err("VALIDATION_ERROR", "Unexpected error.", details=str(ex))
        _log("error", error=e["error"])
        return e

def list_spaces(status=None, limit=None, cursor=None, order=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0167000" if __import__("os").path.isdir("./environment_mix/0167000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list_spaces"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, credential_id=None, details=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            row = {
                "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
                "endpoint": endpoint,
                "credential_id": credential_id,
                "status": status_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _now()
            }
            if details is not None:
                row["details"] = details
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            pass

    # Ambient auth: if there is any workspace/account model it is not provided in schema;
    # allow access by default (UNAUTHORIZED only if a credential is explicitly required, which it is not).

    # Validation
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "disabled", "deleted"):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid status.", field="status")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid limit; must be between 1 and 100.", field="limit")
    if order is None:
        order = "created_at"
    if not isinstance(order, str) or order not in ("created_at", "-created_at", "updated_at", "-updated_at", "name", "-name"):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid order.", field="order")

    def _decode_cursor(c):
        if c is None:
            return 0
        if not isinstance(c, str) or c == "":
            return None
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===").decode("utf-8")
            if not raw.startswith("offset:"):
                return None
            off = int(raw.split(":", 1)[1])
            if off < 0:
                return None
            return off
        except Exception:
            return None

    offset = _decode_cursor(cursor)
    if offset is None:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Malformed cursor.", field="cursor")

    spaces = _load("spaces.json")
    if not isinstance(spaces, list):
        spaces = []

    # Filter
    rows = []
    for s in spaces:
        if not isinstance(s, dict):
            continue
        if status is not None and s.get("status") != status:
            continue
        rows.append(s)

    # Sort
    reverse = order.startswith("-")
    key = order[1:] if reverse else order

    def _key_fn(r):
        v = r.get(key)
        # Ensure stable ordering
        if v is None:
            return ""
        return v

    rows.sort(key=_key_fn, reverse=reverse)

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{next_offset}".encode("utf-8")).decode("utf-8").rstrip("=")

    resp = {
        "items": page,
        "total": total,
        "limit": limit,
        "cursor": cursor,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "order": order,
        "filter": {"status": status} if status is not None else {}
    }
    _log("OK")
    return resp

