def create_environment(space_id, name, contentful_environment_id=None, **_extra):
    import json, os, datetime, time, re, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0167000" if __import__("os").path.isdir("./environment_mix/0167000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "create_environment"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, credential_id=None, details=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            row = {
                "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
                "endpoint": endpoint,
                "credential_id": credential_id,
                "status": status_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": _now()
            }
            if details is not None:
                row["details"] = details
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            pass

    # Validation
    if not isinstance(space_id, str) or not re.match(r"^cfl_space_[0-9A-HJKMNP-TV-Z]{18,}$", space_id):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "space_id is invalid.", field="space_id")
    if not isinstance(name, str) or name.strip() == "":
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name is required and must be non-empty.", field="name")
    if contentful_environment_id is not None:
        if not isinstance(contentful_environment_id, str) or contentful_environment_id.strip() == "":
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "contentful_environment_id must be a non-empty string when provided.", field="contentful_environment_id")
        # Keep it conservative: Contentful env ids are typically [A-Za-z0-9_-]{1,64}
        if not re.match(r"^[A-Za-z0-9][A-Za-z0-9_-]{0,63}$", contentful_environment_id):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "contentful_environment_id is invalid.", field="contentful_environment_id")

    spaces = _load("spaces.json")
    if not isinstance(spaces, list):
        spaces = []
    space = next((s for s in spaces if isinstance(s, dict) and s.get("id") == space_id), None)
    if space is None:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Space not found.", space_id=space_id)

    # Must belong to an active space for environment-scoped operations; creation should respect lifecycle too.
    if space.get("status") != "active":
        _log("INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Cannot create environment in a non-active space.", space_status=space.get("status"))

    envs = _load("environments.json")
    if not isinstance(envs, list):
        envs = []

    # Determine external id
    ext_id = contentful_environment_id.strip() if isinstance(contentful_environment_id, str) else None
    if ext_id is None:
        # Generate a deterministic-ish id from name with uniqueness; mirror common "environment id" concept.
        base = re.sub(r"[^A-Za-z0-9_-]+", "-", name.strip().lower()).strip("-")
        if base == "":
            base = "env"
        ext_id = base[:40]
        used = {e.get("contentful_environment_id") for e in envs if isinstance(e, dict) and e.get("space_id") == space_id}
        if ext_id in used:
            i = 2
            while f"{ext_id}-{i}" in used and i < 10000:
                i += 1
            ext_id = f"{ext_id}-{i}"

    # Uniqueness constraint: unique(space_id, contentful_environment_id)
    for e in envs:
        if not isinstance(e, dict):
            continue
        if e.get("space_id") == space_id and e.get("contentful_environment_id") == ext_id:
            _log("CONFLICT")
            return _err("CONFLICT", "Environment with the same identifier already exists in this space.",
                        space_id=space_id, contentful_environment_id=ext_id)

    now = _now()
    new_id = f"cfl_env_{uuid.uuid4().hex[:26]}"
    env = {
        "id": new_id,
        "space_id": space_id,
        "contentful_environment_id": ext_id,
        "name": name.strip(),
        "status": "creating",
        "created_at": now,
        "updated_at": now
    }
    envs.append(env)
    _save("environments.json", envs)

    # Provisioning: progress to ready (as per business rule). Do it immediately for offline server.
    envs2 = _load("environments.json")
    if not isinstance(envs2, list):
        envs2 = envs
    for e in envs2:
        if isinstance(e, dict) and e.get("id") == new_id:
            # creating -> ready is legal
            e["status"] = "ready"
            e["updated_at"] = _now()
            env = e
            break
    _save("environments.json", envs2)

    _log("OK")
    return {"environment": env}

def delete_environment(environment_id, **_extra):
    import json, os, datetime, time, secrets, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0167000" if __import__("os").path.isdir("./environment_mix/0167000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "delete_environment"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _find_logfile():
        for cand in ("request_logs.json", "usage.json", "audit_logs.json", "api_requests.json"):
            if os.path.exists(os.path.join(_DB, cand)):
                return cand
        return "request_logs.json"
    _LOGF = _find_logfile()

    def _append_log(status, error_code=None, message=None, meta=None):
        try:
            rows = _load(_LOGF)
            if not isinstance(rows, list):
                rows = []
            rec = {
                "id": "req_" + secrets.token_hex(12),
                "endpoint": endpoint,
                "timestamp": _now(),
                "status": status,
                "latency_ms": int((time.time() - _t0) * 1000),
            }
            if error_code is not None:
                rec["error_code"] = error_code
            if message is not None:
                rec["message"] = message
            if meta is not None:
                rec["meta"] = meta
            rows.append(rec)
            _save(_LOGF, rows)
        except Exception:
            return

    try:
        if not isinstance(environment_id, str) or not re.match(r"^cfl_env_[0-9A-Z]{18,}$", environment_id):
            _append_log("VALIDATION_ERROR", "VALIDATION_ERROR", "environment_id is invalid.", {"field": "environment_id"})
            return _err("VALIDATION_ERROR", "environment_id is invalid.", field="environment_id")

        envs = _load("environments.json")
        if not isinstance(envs, list):
            envs = []
        idx = next((i for i, e in enumerate(envs) if isinstance(e, dict) and e.get("id") == environment_id), None)
        if idx is None:
            _append_log("NOT_FOUND", "NOT_FOUND", "Environment not found.", {"environment_id": environment_id})
            return _err("NOT_FOUND", "Environment not found.", environment_id=environment_id)

        env = envs[idx]
        if env.get("status") == "deleted":
            _append_log("CONFLICT", "CONFLICT", "Environment is already deleted.", {"environment_id": environment_id})
            return _err("CONFLICT", "Environment is already deleted.", environment_id=environment_id)

        # Reject delete if any non-deleted content items exist in env.
        items = _load("content_items.json")
        if not isinstance(items, list):
            items = []
        has_live = any(isinstance(it, dict) and it.get("environment_id") == environment_id and it.get("status") != "deleted" for it in items)
        if has_live:
            _append_log("CONFLICT", "CONFLICT", "Environment cannot be deleted while it contains non-deleted content items.", {"environment_id": environment_id})
            return _err("CONFLICT", "Environment cannot be deleted while it contains non-deleted content items.", environment_id=environment_id)

        # Lifecycle: ready -> deleting -> deleted; creating can go -> deleted
        now = _now()
        st = env.get("status")
        if st == "ready":
            env["status"] = "deleting"
            env["updated_at"] = now
            envs[idx] = env
            _save("environments.json", envs)
            # immediately provision deletion completion
            env["status"] = "deleted"
            env["updated_at"] = _now()
            envs[idx] = env
            _save("environments.json", envs)
        elif st == "creating":
            env["status"] = "deleted"
            env["updated_at"] = now
            envs[idx] = env
            _save("environments.json", envs)
        elif st == "deleting":
            # idempotent completion
            env["status"] = "deleted"
            env["updated_at"] = now
            envs[idx] = env
            _save("environments.json", envs)
        else:
            _append_log("INVALID_TRANSITION", "INVALID_TRANSITION", "Environment cannot be deleted from its current state.", {"environment_id": environment_id, "status": st})
            return _err("INVALID_TRANSITION", "Environment cannot be deleted from its current state.", environment_id=environment_id, status=st)

        _append_log("OK", None, None, {"environment_id": environment_id})
        return {"environment": envs[idx]}
    except Exception as e:
        _append_log("VALIDATION_ERROR", "VALIDATION_ERROR", "Unexpected error.", {"detail": str(e)})
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

