            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "bulk_validate"
    CAP = 100

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _find_logfile():
        for cand in ("request_logs.json", "usage.json", "audit_logs.json", "api_requests.json"):
            if os.path.exists(os.path.join(_DB, cand)):
                return cand
        return "request_logs.json"
    _LOGF = _find_logfile()

    def _append_log(status, error_code=None, message=None, meta=None):
        try:
            rows = _load(_LOGF)
            if not isinstance(rows, list):
                rows = []
            rec = {
                "id": "req_" + secrets.token_hex(12),
                "endpoint": endpoint,
                "timestamp": _now(),
                "status": status,
                "latency_ms": int((time.time() - _t0) * 1000),
            }
            if error_code is not None:
                rec["error_code"] = error_code
            if message is not None:
                rec["message"] = message
            if meta is not None:
                rec["meta"] = meta
            rows.append(rec)
            _save(_LOGF, rows)
        except Exception:
            return

    try:
        if not isinstance(environment_id, str) or not re.match(r"^cfl_env_[0-9A-Z]{18,}$", environment_id):
            _append_log("VALIDATION_ERROR", "VALIDATION_ERROR", "environment_id is invalid.", {"field": "environment_id"})
            return _err("VALIDATION_ERROR", "environment_id is invalid.", field="environment_id")
        if not isinstance(entry_ids, list) or len(entry_ids) < 1:
            _append_log("VALIDATION_ERROR", "VALIDATION_ERROR", "entry_ids must be a non-empty array.", {"field": "entry_ids"})
            return _err("VALIDATION_ERROR", "entry_ids must be a non-empty array.", field="entry_ids")
        if len(entry_ids) > CAP:
            _append_log("VALIDATION_ERROR", "VALIDATION_ERROR", "Too many entry_ids.", {"field": "entry_ids", "max": CAP})
            return _err("VALIDATION_ERROR", "Too many entry_ids.", field="entry_ids", max=CAP)
        for eid in entry_ids:
            if not isinstance(eid, str) or not re.match(r"^cfl_item_[0-9A-Z]{18,}$", eid):
                _append_log("VALIDATION_ERROR", "VALIDATION_ERROR", "entry_ids contains an invalid id.", {"field": "entry_ids"})
                return _err("VALIDATION_ERROR", "entry_ids contains an invalid id.", field="entry_ids")

        if locales is not None:
            if not isinstance(locales, list) or len(locales) < 1:
                _append_log("VALIDATION_ERROR", "VALIDATION_ERROR", "locales must be a non-empty array when provided.", {"field": "locales"})
                return _err("VALIDATION_ERROR", "locales must be a non-empty array when provided.", field="locales")
            for loc in locales:
                if not isinstance(loc, str) or not loc:
                    _append_log("VALIDATION_ERROR", "VALIDATION_ERROR", "locales contains an invalid locale.", {"field": "locales"})
                    return _err("VALIDATION_ERROR", "locales contains an invalid locale.", field="locales")

        envs = _load("environments.json")
        if not isinstance(envs, list):
            envs = []
        env = next((e for e in envs if isinstance(e, dict) and e.get("id") == environment_id), None)
        if env is None:
            _append_log("NOT_FOUND", "NOT_FOUND", "Environment not found.", {"environment_id": environment_id})
            return _err("NOT_FOUND", "Environment not found.", environment_id=environment_id)

        spaces = _load("spaces.json")
        if not isinstance(spaces, list):
            spaces = []
        space = next((s for s in spaces if isinstance(s, dict) and s.get("id") == env.get("space_id")), None)
        if not space or space.get("status") != "active":
            _append_log("UNAUTHORIZED", "UNAUTHORIZED", "Space is not active.", {"spaceId": env.get("space_id")})
            return _err("UNAUTHORIZED", "Space is not active.", spaceId=env.get("space_id"))
        if env.get("status") != "ready":
            _append_log("INVALID_TRANSITION", "INVALID_TRANSITION", "Environment is not ready.", {"environment_id": environment_id, "status": env.get("status")})
            return _err("INVALID_TRANSITION", "Environment is not ready.", environment_id=environment_id, status=env.get("status"))

        available_locales = space.get("available_locales") or []
        if not isinstance(available_locales, list) or len(available_locales) < 1:
            _append_log("VALIDATION_ERROR", "VALIDATION_ERROR", "Space locale configuration is invalid.", {"spaceId": space.get("id")})
            return _err("VALIDATION_ERROR", "Space locale configuration is invalid.", spaceId=space.get("id"))
        if locales is not None:
            for loc in locales:
                if loc not in available_locales:
                    _append_log("VALIDATION_ERROR", "VALIDATION_ERROR", "Requested locale is not enabled in space.", {"locale": loc, "allowed_locales": available_locales})
                    return _err("VALIDATION_ERROR", "Requested locale is not enabled in space.", locale=loc, allowed_locales=available_locales)

        items = _load("content_items.json")
        if not isinstance(items, list):
            items = []
        cts = _load("content_types.json")
        if not isinstance(cts, list):
            cts = []

        # Ensure all referenced items exist in env and are entries
        id_to_item = {}
        for eid in entry_ids:
            it = next((x for x in items if isinstance(x, dict) and x.get("id") == eid), None)
            if it is None or it.get("status") == "deleted" or it.get("environment_id") != environment_id:
                _append_log("VALIDATION_ERROR", "VALIDATION_ERROR", "All entry_ids must refer to existing non-deleted entries in the environment.", {"entryId": eid})
                return _err("VALIDATION_ERROR", "All entry_ids must refer to existing non-deleted entries in the environment.", entryId=eid)
            if it.get("type") != "entry":
                _append_log("VALIDATION_ERROR", "VALIDATION_ERROR", "All entry_ids must be entries.", {"entryId": eid})
                return _err("VALIDATION_ERROR", "All entry_ids must be entries.", entryId=eid)
            id_to_item[eid] = it

        def _schema_required_fields(ct_row):
            req = []
            fs = ct_row.get("fields_schema")
            if isinstance(fs, dict):
                fields_list = fs.get("fields")
                if isinstance(fields_list, list):
                    for f in fields_list:
                        if isinstance(f, dict) and f.get("required") is True and isinstance(f.get("id"), str):
                            req.append(f.get("id"))
            return req

        results = []
        for eid in entry_ids:
            it = id_to_item[eid]
            ct_id = it.get("content_type_id")
            ct = next((c for c in cts if isinstance(c, dict) and c.get("id") == ct_id and c.get("environment_id") == environment_id and c.get("status") != "deleted"), None)

            issues = []
            if ct is None:
                issues.append({"code": "NOT_FOUND", "message": "Content type not found for entry.", "content_type_id": ct_id})
                results.append({"entry_id": eid, "ok": False, "issues": issues})
                continue

            required_fields = _schema_required_fields(ct)
            payload = it.get("fields") if isinstance(it.get("fields"), dict) else {}

            # Validate required fields and locale presence and basic type checks for strings/numbers/booleans/arrays/objects.
            fs = ct.get("fields_schema")
            field_defs = {}
            if isinstance(fs, dict) and isinstance(fs.get("fields"), list):
                for f in fs["fields"]:
                    if isinstance(f, dict) and isinstance(f.get("id"), str):
                        field_defs[f["id"]] = f

            locs_to_check = locales[:] if locales is not None else None

            for fid in required_fields:
                if fid not in payload or not isinstance(payload.get(fid), dict) or len(payload.get(fid) or {}) == 0:
                    issues.append({"code": "REQUIRED", "message": "Required field missing.", "field": fid})
                    continue
                loc_obj = payload.get(fid) or {}
                if locs_to_check is None:
                    check_locs = list(loc_obj.keys())
                else:
                    check_locs = locs_to_check
                for loc in check_locs:
                    if loc not in available_locales:
                        issues.append({"code": "LOCALE", "message": "Locale not enabled in space.", "field": fid, "locale": loc})
                        continue
                    if loc not in loc_obj:
                        issues.append({"code": "LOCALE_MISSING", "message": "Missing locale value for required field.", "field": fid, "locale": loc})

            # Type compatibility (basic)
            for fid, loc_obj in payload.items():
                if not isinstance(loc_obj, dict):
                    issues.append({"code": "LOCALE_SHAPE", "message": "Field value must be locale-keyed object.", "field": fid})
                    continue
                fdef = field_defs.get(fid, {})
                ftype = fdef.get("type")
                for loc, val in loc_obj.items():
                    if locs_to_check is not None and loc not in locs_to_check:
                        continue
                    if loc not in available_locales:
                        issues.append({"code": "LOCALE", "message": "Locale not enabled in space.", "field": fid, "locale": loc})
                        continue
                    if ftype in ("Text", "Symbol", "String"):
                        if val is not None and not isinstance(val, str):
                            issues.append({"code": "TYPE", "message": "Expected string.", "field": fid, "locale": loc})
                    elif ftype in ("Number", "Integer"):
                        if val is not None and not isinstance(val, (int, float)):
                            issues.append({"code": "TYPE", "message": "Expected number.", "field": fid, "locale": loc})
                    elif ftype in ("Boolean",):
                        if val is not None and not isinstance(val, bool):
                            issues.append({"code": "TYPE", "message": "Expected boolean.", "field": fid, "locale": loc})
                    elif ftype in ("Array",):
                        if val is not None and not isinstance(val, list):
                            issues.append({"code": "TYPE", "message": "Expected array.", "field": fid, "locale": loc})
                    elif ftype in ("Object", "Json"):
                        if val is not None and not isinstance(val, dict):
                            issues.append({"code": "TYPE", "message": "Expected object.", "field": fid, "locale": loc})
                    else:
                        # unknown type: don't fail, but keep locale shape enforced above
                        pass

            results.append({"entry_id": eid, "ok": len(issues) == 0, "issues": issues})

        _append_log("OK", None, None, {"environment_id": environment_id, "count": len(results)})
        return {"environment_id": environment_id, "results": results}
    except Exception as e:
        _append_log("VALIDATION_ERROR", "VALIDATION_ERROR", "Unexpected error.", {"detail": str(e)})
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

def list_ai_actions(space_id, environment_id=None, status=None, limit=None, cursor=None, order=None, **_extra):
    import json, os, datetime, re, time, base64

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0167000" if __import__("os").path.isdir("./environment_mix/0167000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status_, message=None, **meta):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "ts": _now(),
            "endpoint": endpoint,
            "status": status_,
            "latency_ms": int((time.time() - _t0) * 1000),
            "message": message,
            "meta": meta or {},
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_rate(endpoint, scope_key):
        limits = _load("rate_limits.json")
        if not isinstance(limits, list):
            return None
        rule = None
        for r in limits:
            if isinstance(r, dict) and r.get("endpoint") == endpoint:
                rule = r
                break
        if not rule:
            return None
        try:
            per_minute = int(rule.get("per_minute"))
        except Exception:
            return None
        if per_minute <= 0:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        for e in logs:
            if not isinstance(e, dict):
                continue
            if e.get("endpoint") != endpoint:
                continue
            meta = e.get("meta") or {}
            if meta.get("scope") != scope_key:
                continue
            ts = e.get("ts")
            if isinstance(ts, str):
                try:
                    tsv = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if tsv >= cutoff:
                    cnt += 1
        if cnt >= per_minute:
            return _err("RATE_LIMIT", "Rate limit exceeded", limit=per_minute, window_seconds=60)
        return None

    def _decode_cursor(c):
        if not c:
            return 0
        if not isinstance(c, str):
            return None
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===").decode("utf-8")
            if not raw.startswith("offset:"):
                return None
            return int(raw.split(":", 1)[1])
        except Exception:
            return None

    def _encode_cursor(offset):
        raw = f"offset:{offset}".encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    try:
        if not isinstance(space_id, str) or not re.match(r"^cfl_space_[0-9A-Z]{18,}$", space_id):
            _log("list_ai_actions", "error", "Invalid space_id", scope="global")
            return _err("VALIDATION_ERROR", "space_id is invalid", field="space_id")

        if environment_id is not None:
            if not isinstance(environment_id, str) or not re.match(r"^cfl_env_[0-9A-Z]{18,}$", environment_id):
                _log("list_ai_actions", "error", "Invalid environment_id", scope=space_id)
                return _err("VALIDATION_ERROR", "environment_id is invalid", field="environment_id")

        if status is not None and status not in ("draft", "published", "disabled", "deleted"):
            _log("list_ai_actions", "error", "Invalid status", scope=space_id)
            return _err("VALIDATION_ERROR", "status is invalid", field="status")

        if limit is None:
            limit = 25
        if not isinstance(limit, int) or limit < 1 or limit > 100:
            _log("list_ai_actions", "error", "Invalid limit", scope=space_id)
            return _err("VALIDATION_ERROR", "limit is invalid", field="limit")

        if order is None:
            order = "-updated_at"
        if order not in ("created_at", "-created_at", "updated_at", "-updated_at", "name", "-name"):
            _log("list_ai_actions", "error", "Invalid order", scope=space_id)
            return _err("VALIDATION_ERROR", "order is invalid", field="order")

        offset = _decode_cursor(cursor)
        if offset is None or offset < 0:
            _log("list_ai_actions", "error", "Invalid cursor", scope=space_id)
            return _err("VALIDATION_ERROR", "cursor is invalid", field="cursor")

        spaces = _load("spaces.json")
        if not isinstance(spaces, list):
            spaces = []
        space = next((s for s in spaces if isinstance(s, dict) and s.get("id") == space_id), None)
        if not space:
            _log("list_ai_actions", "error", "Space not found", scope=space_id)
            return _err("NOT_FOUND", "Space not found", space_id=space_id)

        # Ambient auth: ensure some workable context; here: space must not be deleted
        if space.get("status") == "deleted":
            _log("list_ai_actions", "error", "Space deleted", scope=space_id)
            return _err("UNAUTHORIZED", "Space is deleted", space_id=space_id)

        rl = _enforce_rate("list_ai_actions", scope_key=space_id)
        if rl:
            _log("list_ai_actions", "error", rl["error"]["message"], scope=space_id)
            return rl

        envs = _load("environments.json")
        if not isinstance(envs, list):
            envs = []
        env_ids_in_space = {e.get("id") for e in envs if isinstance(e, dict) and e.get("space_id") == space_id}

        if environment_id is not None:
            env = next((e for e in envs if isinstance(e, dict) and e.get("id") == environment_id and e.get("space_id") == space_id), None)
            if not env:
                _log("list_ai_actions", "error", "Environment not found in space", scope=space_id, environment_id=environment_id)
                return _err("NOT_FOUND", "Environment not found in space", environment_id=environment_id, space_id=space_id)
            env_ids_in_space = {environment_id}

        acts = _load("ai_actions.json")
        if not isinstance(acts, list):
            acts = []

        rows = [
            a for a in acts
            if isinstance(a, dict)
            and a.get("environment_id") in env_ids_in_space
            and (status is None or a.get("status") == status)
        ]

        key = order.lstrip("-")
        desc = order.startswith("-")

        def _sort_key(a):
            v = a.get(key)
            if v is None:
                return ""
            return v

        rows.sort(key=_sort_key, reverse=desc)

        total = len(rows)
        page = rows[offset: offset + limit]
        next_off = offset + len(page)
        has_more = next_off < total
        next_cursor = _encode_cursor(next_off) if has_more else None

        _log("list_ai_actions", "ok", scope=space_id, returned=len(page), total=total, offset=offset)
        return {
            "items": [dict(x) for x in page],
            "meta": {
                "total": total,
                "limit": limit,
                "cursor": cursor,
                "next_cursor": next_cursor,
                "has_more": has_more,
                "order": order,
            }
        }
    except Exception as e:
        _log("list_ai_actions", "error", "Internal error", scope="global", detail=str(e))
        return _err("CONFLICT", "Internal error")

def get_ai_action(ai_action_id, **_extra):
    import json, os, datetime, re, time

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0167000" if __import__("os").path.isdir("./environment_mix/0167000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
