        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(time.time()*1000)}_{len(logs)+1}",
            "ts": _now(),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int((time.time() - _t0) * 1000),
            "message": message,
            "meta": meta or {},
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_rate(endpoint, scope_key):
        # If no rate limits configured, do nothing.
        limits = _load("rate_limits.json")
        if not isinstance(limits, list):
            return None
        rule = None
        for r in limits:
            if isinstance(r, dict) and r.get("endpoint") == endpoint:
                rule = r
                break
        if not rule:
            return None
        try:
            per_minute = int(rule.get("per_minute"))
        except Exception:
            return None
        if per_minute <= 0:
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        cnt = 0
        for e in logs:
            if not isinstance(e, dict):
                continue
            if e.get("endpoint") != endpoint:
                continue
            meta = e.get("meta") or {}
            if meta.get("scope") != scope_key:
                continue
            ts = e.get("ts")
            if isinstance(ts, str):
                try:
                    tsv = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    continue
                if tsv >= cutoff:
                    cnt += 1
        if cnt >= per_minute:
            return _err("QUOTA_EXCEEDED", "Request quota exceeded", limit=per_minute, window_seconds=60)
        return None

    try:
        if not isinstance(ai_action_id, str) or not re.match(r"^cfl_aiact_[0-9A-Z]{18,}$", ai_action_id):
            _log("get_ai_action", "error", "Invalid ai_action_id", scope="global")
            return _err("VALIDATION_ERROR", "ai_action_id is invalid", field="ai_action_id")

        acts = _load("ai_actions.json")
        if not isinstance(acts, list):
            acts = []
        act = next((a for a in acts if isinstance(a, dict) and a.get("id") == ai_action_id), None)
        if not act:
            _log("get_ai_action", "error", "AI action not found", scope=ai_action_id)
            return _err("NOT_FOUND", "AI Action not found", ai_action_id=ai_action_id)

        envs = _load("environments.json")
        if not isinstance(envs, list):
            envs = []
        env = next((e for e in envs if isinstance(e, dict) and e.get("id") == act.get("environment_id")), None)
        if not env:
            _log("get_ai_action", "error", "Environment not found for AI action", scope=ai_action_id)
            return _err("NOT_FOUND", "Environment not found for AI Action", environment_id=act.get("environment_id"))

        spaces = _load("spaces.json")
        if not isinstance(spaces, list):
            spaces = []
        space = next((s for s in spaces if isinstance(s, dict) and s.get("id") == env.get("space_id")), None)
        if not space:
            _log("get_ai_action", "error", "Space not found for AI action", scope=ai_action_id)
            return _err("NOT_FOUND", "Space not found for AI Action", space_id=env.get("space_id"))

        # Ambient auth: require a workable scope; for reads allow space not deleted, env can be non-ready but not deleted
        if space.get("status") == "deleted" or env.get("status") == "deleted":
            _log("get_ai_action", "error", "Unauthorized scope", scope=ai_action_id)
            return _err("UNAUTHORIZED", "AI Action not accessible", ai_action_id=ai_action_id)

        rl = _enforce_rate("get_ai_action", scope_key=space.get("id"))
        if rl:
            _log("get_ai_action", "error", rl["error"]["message"], scope=space.get("id"))
            return rl

        _log("get_ai_action", "ok", scope=ai_action_id, environment_id=env.get("id"), space_id=space.get("id"))
        return {"ai_action": dict(act)}
    except Exception as e:
        _log("get_ai_action", "error", "Internal error", scope="global", detail=str(e))
        return _err("CONFLICT", "Internal error")

def create_ai_action(environment_id, name, definition, description=None, **_extra):
    import json, os, datetime, time, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0167000" if __import__("os").path.isdir("./environment_mix/0167000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "create_ai_action"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _find_logfile():
        for cand in ("request_logs.json", "usage.json", "audit_logs.json", "api_requests.json"):
            if os.path.exists(os.path.join(_DB, cand)):
                return cand
        return "request_logs.json"

    _LOGF = _find_logfile()

    def _read_logs():
        logs = _load(_LOGF)
        return logs if isinstance(logs, list) else []

    def _write_log(status, error_code=None, message=None, scope=None):
        logs = _read_logs()
        rec = {
            "id": "req_" + secrets.token_hex(12),
            "endpoint": endpoint,
            "timestamp": _now(),
            "status": status,
            "latency_ms": int((time.time() - _t0) * 1000),
        }
        if message is not None:
            rec["message"] = message
        meta = {}
        if scope is not None:
            meta["scope"] = scope
        if meta:
            rec["meta"] = meta
        if error_code is not None:
            rec["error_code"] = error_code
        logs.append(rec)
        _save(_LOGF, logs)

    def _rate_limit_check(scope):
        limits = _load("rate_limits.json")
        if not isinstance(limits, list):
            return None
        rule = None
        for r in limits:
            if isinstance(r, dict) and (r.get("endpoint") == endpoint or r.get("tool") == endpoint):
                rule = r
                break
        if not rule:
            return None
        try:
            if rule.get("per_minute") is not None:
                window = 60
                limit = int(rule.get("per_minute"))
            else:
                window = int(rule.get("window_seconds") or 60)
                limit = int(rule.get("max_requests") or 0)
        except Exception:
            return None
        if limit <= 0:
            return None
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window)
        cnt = 0
        for e in _read_logs():
            if not isinstance(e, dict):
                continue
            if (e.get("endpoint") or e.get("tool")) != endpoint:
                continue
            meta = e.get("meta") or {}
            if scope is not None and meta.get("scope") != scope:
                continue
            ts = _parse_ts(e.get("timestamp") or e.get("ts") or e.get("created_at"))
            if ts and ts >= cutoff:
                cnt += 1
        if cnt >= limit:
            return _err("RATE_LIMIT", "Rate limit exceeded", window_seconds=window, max_requests=limit)
        return None

    # Validation
    if not isinstance(environment_id, str) or environment_id.strip() == "":
        e = _err("VALIDATION_ERROR", "environment_id must be a non-empty string.", field="environment_id")
        _write_log("error", error_code=e["error"]["code"], message=e["error"]["message"], scope=environment_id if isinstance(environment_id, str) else None)
        return e
    if not isinstance(name, str) or name.strip() == "":
        e = _err("VALIDATION_ERROR", "name must be a non-empty string.", field="name")
        _write_log("error", error_code=e["error"]["code"], message=e["error"]["message"], scope=environment_id)
        return e
    if not isinstance(definition, dict):
        e = _err("VALIDATION_ERROR", "definition must be an object.", field="definition")
        _write_log("error", error_code=e["error"]["code"], message=e["error"]["message"], scope=environment_id)
        return e
    if description is not None and not isinstance(description, str):
        e = _err("VALIDATION_ERROR", "description must be a string when provided.", field="description")
        _write_log("error", error_code=e["error"]["code"], message=e["error"]["message"], scope=environment_id)
        return e

    rl = _rate_limit_check(environment_id)
    if rl:
        _write_log("error", error_code=rl["error"]["code"], message=rl["error"]["message"], scope=environment_id)
        return rl

    envs = _load("environments.json")
    spaces = _load("spaces.json")
    actions = _load("ai_actions.json")
    if not isinstance(envs, list): envs = []
    if not isinstance(spaces, list): spaces = []
    if not isinstance(actions, list): actions = []

    env = next((e for e in envs if isinstance(e, dict) and e.get("id") == environment_id), None)
    if not env:
        e = _err("NOT_FOUND", "Environment does not exist.", environment_id=environment_id)
        _write_log("error", error_code=e["error"]["code"], message=e["error"]["message"], scope=environment_id)
        return e
    space = next((s for s in spaces if isinstance(s, dict) and s.get("id") == env.get("space_id")), None)
    if not space:
        e = _err("NOT_FOUND", "Parent space does not exist.", space_id=env.get("space_id"))
        _write_log("error", error_code=e["error"]["code"], message=e["error"]["message"], scope=environment_id)
        return e
    if space.get("status") != "active" or env.get("status") != "ready":
        e = _err("INVALID_TRANSITION", "Environment must be ready and its space must be active.", space_status=space.get("status"), environment_status=env.get("status"))
        _write_log("error", error_code=e["error"]["code"], message=e["error"]["message"], scope=environment_id)
        return e

    # Conflict: same name in environment (ignore deleted)
    for a in actions:
        if not isinstance(a, dict):
            continue
        if a.get("environment_id") == environment_id and a.get("status") != "deleted" and a.get("name") == name:
            e = _err("CONFLICT", "An AI Action with the same name already exists in this environment.", name=name)
            _write_log("error", error_code=e["error"]["code"], message=e["error"]["message"], scope=environment_id)
            return e

    def _new_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "".join(secrets.choice(alphabet) for _ in range(20))

    now = _now()
    new_action = {
        "id": _new_id("cfl_aiact_"),
        "environment_id": environment_id,
        "contentful_ai_action_id": "aiact_" + secrets.token_hex(8),
        "name": name,
        "description": description,
        "definition": definition,
        "sys_version": 1,
        "published_version": None,
        "status": "draft",
        "created_at": now,
        "updated_at": now,
    }
    actions.append(new_action)
    _save("ai_actions.json", actions)

    _write_log("ok", scope=environment_id)
    return {"ai_action": new_action}

def update_ai_action(ai_action_id, sys_version, name=None, description=None, definition=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0167000" if __import__("os").path.isdir("./environment_mix/0167000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    logs_file = None
    for cand in ("request_logs.json", "usage.json", "audit_logs.json", "api_requests.json"):
        if os.path.exists(os.path.join(_DB, cand)):
            logs_file = cand
            break

    def _log(status, error_code=None):
        if not logs_file:
            return
        logs = _load(logs_file)
        rec = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "update_ai_action",
            "timestamp": now,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if error_code:
            rec["error_code"] = error_code
        logs.append(rec)
        _save(logs_file, logs)

    # rate limit: 120/min if logs exist
    if logs_file:
        logs = _load(logs_file)
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
        def _parse_ts(s):
            try:
                if isinstance(s, str) and s.endswith("Z"):
                    return datetime.datetime.fromisoformat(s[:-1])
                if isinstance(s, str):
                    return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
            return None
        recent = 0
        for r in logs:
            if isinstance(r, dict):
                ts = _parse_ts(r.get("timestamp") or r.get("created_at") or r.get("ts"))
                if ts and ts >= cutoff:
                    recent += 1
        if recent >= 120:
            _log("error", error_code="RATE_LIMIT")
            return _err("RATE_LIMIT", "Rate limit exceeded")

    if not isinstance(ai_action_id, str) or not re.match(r"^cfl_aiact_[0-9A-Z]{18,}$", ai_action_id or ""):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "ai_action_id is invalid")
    if not isinstance(sys_version, int) or sys_version < 1:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sys_version must be an integer >= 1")
    if name is not None and (not isinstance(name, str) or len(name.strip()) < 1):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name must be a non-empty string when provided")
    if description is not None and not isinstance(description, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "description must be a string when provided")
    if definition is not None and (not isinstance(definition, dict) or len(definition) == 0):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "definition must be a non-empty object when provided")

    ai_actions = _load("ai_actions.json")
    envs = _load("environments.json")
    spaces = _load("spaces.json")

    idx = next((i for i, a in enumerate(ai_actions) if isinstance(a, dict) and a.get("id") == ai_action_id), None)
    if idx is None:
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "AI Action not found")

    action = ai_actions[idx]
    if action.get("status") == "deleted":
        _log("error", error_code="NOT_FOUND")
        return _err("NOT_FOUND", "AI Action not found")

    if action.get("sys_version") != sys_version:
        _log("error", error_code="CONFLICT")
        return _err("CONFLICT", "sys_version does not match current version", current_sys_version=action.get("sys_version"))

    env = next((e for e in envs if isinstance(e, dict) and e.get("id") == action.get("environment_id")), None)
    if not env:
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No environment context available for this AI Action")
    if env.get("status") != "ready":
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Environment is not ready", status=env.get("status"))

    space = next((s for s in spaces if isinstance(s, dict) and s.get("id") == env.get("space_id")), None)
    if not space or space.get("status") != "active":
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Space is not active")

    # Uniqueness check for name within environment
    if name is not None:
        for a in ai_actions:
            if not isinstance(a, dict):
                continue
            if a.get("id") == ai_action_id:
                continue
            if a.get("environment_id") == action.get("environment_id") and a.get("status") != "deleted" and a.get("name") == name.strip():
                _log("error", error_code="CONFLICT")
                return _err("CONFLICT", "An AI Action with the same name already exists in this environment")

    # If currently published, updating should move it back to draft (rule for content types; align similarly)
    # This is also consistent with "refuse state" note: do not allow edits if deleted.
    new_status = action.get("status")
    if action.get("status") == "published":
        new_status = "draft"

    if name is not None:
        action["name"] = name.strip()
    if description is not None:
        action["description"] = description
    if definition is not None:
        action["definition"] = definition

    action["sys_version"] = int(action.get("sys_version") or 1) + 1
    action["status"] = new_status
    action["updated_at"] = now

    ai_actions[idx] = action
    _save("ai_actions.json", ai_actions)

    _log("ok")
    return {"ai_action": action}

def delete_ai_action(ai_action_id, **_extra):
    import json, os, datetime, time, secrets, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0167000" if __import__("os").path.isdir("./environment_mix/0167000") else "/app/database")
    def _load(n):
