            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    endpoint = "delete_ai_action"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _find_logfile():
        for cand in ("request_logs.json", "usage.json", "audit_logs.json", "api_requests.json"):
            if os.path.exists(os.path.join(_DB, cand)):
                return cand
        return "request_logs.json"
    _LOGF = _find_logfile()

    def _append_log(status, error_code=None, message=None, meta=None):
        try:
            rows = _load(_LOGF)
            if not isinstance(rows, list):
                rows = []
            rows.append({
                "id": "req_" + secrets.token_hex(12),
                "endpoint": endpoint,
                "timestamp": _now(),
                "status": status,
                "error_code": error_code,
                "message": message,
                "latency_ms": int((time.time() - _t0) * 1000),
                "meta": meta or {}
            })
            _save(_LOGF, rows)
        except Exception:
            return

    try:
        if not isinstance(ai_action_id, str) or not re.match(r"^cfl_aiact_[0-9A-Z]{18,}$", ai_action_id):
            _append_log("VALIDATION_ERROR", "VALIDATION_ERROR", "ai_action_id is invalid.", {"field": "ai_action_id"})
            return _err("VALIDATION_ERROR", "ai_action_id is invalid.", field="ai_action_id")

        actions = _load("ai_actions.json")
        if not isinstance(actions, list):
            actions = []
        idx = next((i for i, a in enumerate(actions) if isinstance(a, dict) and a.get("id") == ai_action_id), None)
        if idx is None:
            _append_log("NOT_FOUND", "NOT_FOUND", "AI Action not found.", {"ai_action_id": ai_action_id})
            return _err("NOT_FOUND", "AI Action not found.", ai_action_id=ai_action_id)

        act = actions[idx]
        st = act.get("status")
        # Cannot delete if currently published (must be draft/disabled to delete).
        if st == "published":
            _append_log("CONFLICT", "CONFLICT", "AI Action is published and cannot be deleted.", {"ai_action_id": ai_action_id})
            return _err("CONFLICT", "AI Action is published and cannot be deleted.", ai_action_id=ai_action_id)
        if st == "deleted":
            _append_log("CONFLICT", "CONFLICT", "AI Action is already deleted.", {"ai_action_id": ai_action_id})
            return _err("CONFLICT", "AI Action is already deleted.", ai_action_id=ai_action_id)

        now = _now()
        act["status"] = "deleted"
        act["updated_at"] = now
        actions[idx] = act
        _save("ai_actions.json", actions)

        _append_log("OK", None, None, {"ai_action_id": ai_action_id})
        return {"ai_action": act}
    except Exception as e:
        _append_log("VALIDATION_ERROR", "VALIDATION_ERROR", "Unexpected error.", {"detail": str(e)})
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

