def unpublish_ai_action(ai_action_id, environment_id, sys_version=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0167000" if __import__("os").path.isdir("./environment_mix/0167000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate inputs
    if not isinstance(ai_action_id, str) or not re.match(r"^cfl_aiact_[0-9A-Z]{18,}$", ai_action_id):
        return _err("VALIDATION_ERROR", "Invalid ai_action_id.")
    if not isinstance(environment_id, str) or not re.match(r"^cfl_env_[0-9A-Z]{18,}$", environment_id):
        return _err("VALIDATION_ERROR", "Invalid environment_id.")
    if sys_version is not None and (not isinstance(sys_version, int) or sys_version < 1):
        return _err("VALIDATION_ERROR", "Invalid sys_version; must be an integer >= 1.")

    # Load data
    envs = _load("environments.json")
    spaces = _load("spaces.json")
    actions = _load("ai_actions.json")

    # Resolve environment
    env = next((e for e in envs if e.get("id") == environment_id), None)
    if not env:
        return _err("NOT_FOUND", "Environment not found.")
    space = next((s for s in spaces if s.get("id") == env.get("space_id")), None)
    if not space:
        return _err("NOT_FOUND", "Parent space not found.")
    if space.get("status") != "active" or env.get("status") != "ready":
        return _err("INVALID_TRANSITION", "Environment is not ready or space is not active.", space_status=space.get("status"), environment_status=env.get("status"))

    # Resolve action in env
    act_i = next((i for i, a in enumerate(actions) if a.get("id") == ai_action_id and a.get("environment_id") == environment_id), None)
    if act_i is None:
        return _err("NOT_FOUND", "AI Action not found in the specified Environment.")
    act = actions[act_i]

    # Optimistic locking
    if sys_version is not None and act.get("sys_version") != sys_version:
        return _err("CONFLICT", "VERSION_MISMATCH: sys_version does not match current value.", current_sys_version=act.get("sys_version"))

    # Transition: published -> draft only (Contentful-like)
    if act.get("status") != "published":
        return _err("INVALID_TRANSITION", "AI Action is not published and cannot be unpublished.", status=act.get("status"))

    now = _iso_now()
    act["status"] = "draft"
    act["sys_version"] = int(act.get("sys_version") or 1) + 1
    act["updated_at"] = now
    # Keep published_version as historical marker; do not clear.

    actions[act_i] = act
    _save("ai_actions.json", actions)

    return {
        "ai_action": act,
        "meta": {
            "environment_id": environment_id,
            "space_id": env.get("space_id"),
            "latency_ms": int((time.time() - t0) * 1000)
        }
    }

