                rows = []
            rec = {
                "id": "req_" + secrets.token_hex(12),
                "endpoint": endpoint,
                "timestamp": _now(),
                "status": status,
                "latency_ms": int((time.time() - _t0) * 1000),
            }
            if error_code is not None:
                rec["error_code"] = error_code
            if message is not None:
                rec["message"] = message
            if meta is not None:
                rec["meta"] = meta
            rows.append(rec)
            _save(_LOGF, rows)
        except Exception:
            return

    try:
        if not isinstance(ai_action_id, str) or not re.match(r"^cfl_aiact_[0-9A-Z]{18,}$", ai_action_id):
            _append_log("VALIDATION_ERROR", "VALIDATION_ERROR", "ai_action_id is invalid.", {"field": "ai_action_id"})
            return _err("VALIDATION_ERROR", "ai_action_id is invalid.", field="ai_action_id")
        if not isinstance(environment_id, str) or not re.match(r"^cfl_env_[0-9A-Z]{18,}$", environment_id):
            _append_log("VALIDATION_ERROR", "VALIDATION_ERROR", "environment_id is invalid.", {"field": "environment_id"})
            return _err("VALIDATION_ERROR", "environment_id is invalid.", field="environment_id")
        if not isinstance(variables, dict):
            _append_log("VALIDATION_ERROR", "VALIDATION_ERROR", "variables must be an object.", {"field": "variables"})
            return _err("VALIDATION_ERROR", "variables must be an object.", field="variables")
        if idempotency_key is not None:
            if not isinstance(idempotency_key, str) or not (1 <= len(idempotency_key) <= 255):
                _append_log("VALIDATION_ERROR", "VALIDATION_ERROR", "idempotency_key is invalid.", {"field": "idempotency_key"})
                return _err("VALIDATION_ERROR", "idempotency_key is invalid.", field="idempotency_key")

        envs = _load("environments.json")
        if not isinstance(envs, list):
            envs = []
        env = next((e for e in envs if isinstance(e, dict) and e.get("id") == environment_id), None)
        if env is None:
            _append_log("NOT_FOUND", "NOT_FOUND", "Environment not found.", {"environment_id": environment_id})
            return _err("NOT_FOUND", "Environment not found.", environment_id=environment_id)
        if env.get("status") != "ready":
            _append_log("INVALID_TRANSITION", "INVALID_TRANSITION", "Environment is not ready.", {"environment_id": environment_id, "status": env.get("status")})
            return _err("INVALID_TRANSITION", "Environment is not ready.", environment_id=environment_id, status=env.get("status"))

        spaces = _load("spaces.json")
        if not isinstance(spaces, list):
            spaces = []
        space = next((s for s in spaces if isinstance(s, dict) and s.get("id") == env.get("space_id")), None)
        if not space or space.get("status") != "active":
            _append_log("UNAUTHORIZED", "UNAUTHORIZED", "Space is not active.", {"spaceId": env.get("space_id")})
            return _err("UNAUTHORIZED", "Space is not active.", spaceId=env.get("space_id"))

        actions = _load("ai_actions.json")
        if not isinstance(actions, list):
            actions = []
        act = next((a for a in actions if isinstance(a, dict) and a.get("id") == ai_action_id), None)
        if act is None or act.get("status") == "deleted":
            _append_log("NOT_FOUND", "NOT_FOUND", "AI Action not found.", {"ai_action_id": ai_action_id})
            return _err("NOT_FOUND", "AI Action not found.", ai_action_id=ai_action_id)
        if act.get("environment_id") != environment_id:
            _append_log("UNAUTHORIZED", "UNAUTHORIZED", "AI Action not in requested environment.", {"ai_action_id": ai_action_id, "environment_id": environment_id})
            return _err("UNAUTHORIZED", "AI Action not in requested environment.", ai_action_id=ai_action_id, environment_id=environment_id)
        if act.get("status") != "published":
            _append_log("CONFLICT", "CONFLICT", "AI Action must be published to be invoked.", {"ai_action_id": ai_action_id, "status": act.get("status")})
            return _err("CONFLICT", "AI Action must be published to be invoked.", ai_action_id=ai_action_id, status=act.get("status"))

        invs = _load("ai_action_invocations.json")
        if not isinstance(invs, list):
            invs = []

        # Idempotency: find existing invocation with same key+ai_action+env.
        if idempotency_key is not None:
            existing = next((r for r in invs if isinstance(r, dict)
                             and r.get("environment_id") == environment_id
                             and r.get("ai_action_id") == ai_action_id
                             and r.get("request_variables") == variables
                             and r.get("idempotency_key") == idempotency_key), None)
            if existing is not None:
                _append_log("OK", None, None, {"ai_action_id": ai_action_id, "environment_id": environment_id, "idempotency_key": idempotency_key, "reused": True})
                return {"invocation": existing}

        def _gen_id(prefix):
            return prefix + secrets.token_hex(12).upper()
        existing_ids = {r.get("id") for r in invs if isinstance(r, dict)}
        new_id = _gen_id("cfl_aiinv_")
        while new_id in existing_ids:
            new_id = _gen_id("cfl_aiinv_")

        now = _now()
        inv = {
            "id": new_id,
            "ai_action_id": ai_action_id,
            "environment_id": environment_id,
            "request_variables": variables,
            "status": "queued",
            "result": None,
            "error": None,
            "started_at": None,
            "finished_at": None,
            "expires_at": None,
            "created_at": now,
            "updated_at": now,
        }
        if idempotency_key is not None:
            inv["idempotency_key"] = idempotency_key

        invs.append(inv)
        _save("ai_action_invocations.json", invs)

        _append_log("OK", None, None, {"ai_action_id": ai_action_id, "environment_id": environment_id, "invocation_id": new_id})
        return {"invocation": inv}
    except Exception as e:
        _append_log("VALIDATION_ERROR", "VALIDATION_ERROR", "Unexpected error.", {"detail": str(e)})
        return _err("VALIDATION_ERROR", "Unexpected error.", detail=str(e))

