def update_space(spaceId, name=None, defaultLocale=None, availableLocales=None, status=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0167000" if __import__("os").path.isdir("./environment_mix/0167000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- usage / audit logging + rate limiting (best-effort, schema not provided) ----
    def _log(status_code, credential=None, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        # Try common filenames; if none exist, do not create new collections.
        candidates = [
            "request_logs.json",
            "requests.json",
            "audit_log.json",
            "audit_logs.json",
            "usage.json",
            "usage_logs.json",
        ]
        chosen = None
        for fn in candidates:
            if os.path.exists(os.path.join(_DB, fn)):
                chosen = fn
                break
        if not chosen:
            return

        rows = _load(chosen)
        if not isinstance(rows, list):
            rows = []

        row = {
            "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(rows)+1}",
            "endpoint": "update_space",
            "timestamp": now,
            "status": status_code,
            "latency_ms": latency_ms,
        }
        if credential is not None:
            row["credential"] = credential
        if error_code is not None:
            row["error_code"] = error_code
        rows.append(row)
        _save(chosen, rows)

        # Enforce basic rate limit if a policy file exists
        # (We cannot infer vendor policy; only enforce if explicitly configured)
        policy_fn = "rate_limits.json"
        if os.path.exists(os.path.join(_DB, policy_fn)):
            pol = _load(policy_fn)
            # Expected shapes (best-effort):
            # {"per_minute": 60} OR {"update_space":{"per_minute":60}} OR list of rules
            per_min = None
            if isinstance(pol, dict):
                if isinstance(pol.get("update_space"), dict):
                    per_min = pol["update_space"].get("per_minute")
                if per_min is None:
                    per_min = pol.get("per_minute")
            elif isinstance(pol, list):
                for r in pol:
                    if isinstance(r, dict) and r.get("endpoint") == "update_space":
                        per_min = r.get("per_minute")
                        break
            if isinstance(per_min, int) and per_min > 0:
                # count requests in last 60s
                cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
                def _parse_ts(s):
                    try:
                        if isinstance(s, str) and s.endswith("Z"):
                            s = s[:-1]
                        return datetime.datetime.fromisoformat(s)
                    except Exception:
                        return None
                cnt = 0
                for r in rows:
                    if not isinstance(r, dict):
                        continue
                    if r.get("endpoint") != "update_space":
                        continue
                    ts = _parse_ts(r.get("timestamp"))
                    if ts and ts >= cutoff:
                        cnt += 1
                if cnt > per_min:
                    raise RuntimeError("__RATE_LIMIT__")  # handled below

    # ---- input validation ----
    if not isinstance(spaceId, str) or not re.match(r"^cfl_space_[0-9A-Z]{18,}$", spaceId or ""):
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "spaceId must match ^cfl_space_[0-9A-Z]{18,}$", field="spaceId")

    if name is not None:
        if not isinstance(name, str):
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "name must be a string", field="name")
        if len(name) < 1 or len(name) > 255:
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "name length must be between 1 and 255", field="name")

    locale_pat = re.compile(r"^[a-z]{2}(-[A-Z]{2})?$")

    if defaultLocale is not None:
        if not isinstance(defaultLocale, str) or not locale_pat.match(defaultLocale):
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "defaultLocale must match locale pattern like 'en' or 'en-US'", field="defaultLocale")

    if availableLocales is not None:
        if not isinstance(availableLocales, list):
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "availableLocales must be an array of locale codes", field="availableLocales")
        if len(availableLocales) < 1 or len(availableLocales) > 50:
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "availableLocales must have 1..50 items", field="availableLocales")
        for i, loc in enumerate(availableLocales):
            if not isinstance(loc, str) or not locale_pat.match(loc):
                _log(400, error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "availableLocales contains invalid locale code", field="availableLocales", index=i)
        # normalize: keep order but remove duplicates
        seen = set()
        norm = []
        for loc in availableLocales:
            if loc not in seen:
                seen.add(loc)
                norm.append(loc)
        availableLocales = norm

    if status is not None:
        if status not in ("active", "disabled", "deleted"):
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status must be one of active, disabled, deleted", field="status")

    # Need at least one mutable update (no-op should not succeed without effect)
    if name is None and defaultLocale is None and availableLocales is None and status is None:
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "No updates provided; specify at least one of name, defaultLocale, availableLocales, status")

    # ---- load space ----
    spaces = _load("spaces.json")
    if not isinstance(spaces, list):
        spaces = []

    idx = None
    for i, s in enumerate(spaces):
        if isinstance(s, dict) and s.get("id") == spaceId:
            idx = i
            break
    if idx is None:
        _log(404, error_code="NOT_FOUND")
        return _err("NOT_FOUND", "Space not found", spaceId=spaceId)

    space = dict(spaces[idx])  # work on copy

    # ---- enforce immutability (ids not in input schema, but double-check for safety) ----
    # If caller somehow passes extra properties via **_extra, ignore by contract; additionalProperties=false.

    # ---- enforce lifecycle transitions ----
    transitions = {
        "active": {"disabled", "deleted"},
        "disabled": {"active", "deleted"},
        "deleted": set(),
    }
    current_status = space.get("status")
    if current_status not in transitions:
        _log(409, error_code="CONFLICT")
        return _err("CONFLICT", "Space has unknown status in datastore", status=current_status)

    if status is not None and status != current_status:
        if status not in transitions.get(current_status, set()):
            _log(409, error_code="INVALID_TRANSITION")
            return _err(
                "INVALID_TRANSITION",
                f"Cannot transition space status from {current_status} to {status}",
                from_status=current_status,
                to_status=status,
            )

    # ---- locale constraints ----
    # Compute prospective locales after update
    new_available = space.get("available_locales")
    new_default = space.get("default_locale")

    if availableLocales is not None:
        new_available = availableLocales
    if defaultLocale is not None:
        new_default = defaultLocale

    if new_available is None or not isinstance(new_available, list) or len(new_available) < 1:
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "availableLocales must have at least one locale", field="availableLocales")

    if not isinstance(new_default, str) or not locale_pat.match(new_default):
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "defaultLocale must be a valid locale code", field="defaultLocale")

    if new_default not in new_available:
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "defaultLocale must be included in availableLocales", field="defaultLocale")

    # If removing locales, refuse if it would invalidate existing non-deleted entry/asset content
    removing = set(space.get("available_locales") or []) - set(new_available)
    if removing:
        envs = _load("environments.json")
        items = _load("content_items.json")
        if not isinstance(envs, list):
            envs = []
        if not isinstance(items, list):
            items = []

        env_ids = {e.get("id") for e in envs if isinstance(e, dict) and e.get("space_id") == spaceId and e.get("status") != "deleted"}
        # check entry fields and asset_meta for locales
        bad_refs = []
        for it in items:
            if not isinstance(it, dict):
                continue
            if it.get("environment_id") not in env_ids:
                continue
            if it.get("status") == "deleted":
                continue

            if it.get("type") == "entry":
                fields = it.get("fields") or {}
                if not isinstance(fields, dict):
                    continue
                for fid, locmap in fields.items():
                    if not isinstance(locmap, dict):
                        continue
                    for loc in locmap.keys():
                        if loc in removing:
                            bad_refs.append({"item_id": it.get("id"), "contentful_item_id": it.get("contentful_item_id"), "field": fid, "locale": loc})
                            if len(bad_refs) >= 20:
                                break
                    if len(bad_refs) >= 20:
                        break
            elif it.get("type") == "asset":
                meta = it.get("asset_meta") or {}
                if not isinstance(meta, dict):
                    continue
                for k, v in meta.items():
                    if isinstance(v, dict):
                        for loc in v.keys():
                            if loc in removing:
                                bad_refs.append({"item_id": it.get("id"), "contentful_item_id": it.get("contentful_item_id"), "asset_key": k, "locale": loc})
                                if len(bad_refs) >= 20:
                                    break
                    if len(bad_refs) >= 20:
                        break

            if len(bad_refs) >= 20:
                break

        if bad_refs:
            _log(409, error_code="CONFLICT")
            return _err(
                "CONFLICT",
                "availableLocales update would invalidate existing content that uses removed locales",
                removed_locales=sorted(list(removing)),
                examples=bad_refs,
            )

    # ---- unique(name?) not declared; unique(contentful_space_id) is immutable anyway. Enforce non-empty name already. ----

    # ---- apply updates; ensure effect ----
    changed = False

    if name is not None and name != space.get("name"):
        space["name"] = name
        changed = True

    if availableLocales is not None and availableLocales != space.get("available_locales"):
        space["available_locales"] = new_available
        changed = True

    if defaultLocale is not None and defaultLocale != space.get("default_locale"):
        space["default_locale"] = new_default
        changed = True

    if status is not None and status != space.get("status"):
        space["status"] = status
        changed = True

    if not changed:
        # No success without effect (idempotent update with same values is treated as no-op -> conflict/validation?)
        _log(409, error_code="CONFLICT")
        return _err("CONFLICT", "Update would not change any mutable fields")

    space["updated_at"] = now

    # ---- persist ----
    spaces[idx] = space
    _save("spaces.json", spaces)

    # ---- log + return ----
    try:
        _log(200)
    except RuntimeError as e:
        if str(e) == "__RATE_LIMIT__":
            # record refusal too
            _log(429, error_code="RATE_LIMIT")
            return _err("RATE_LIMIT", "Too many requests")
        raise

    return {
        "space": space
    }
